--
-- Name: acs__add_user(integer, character varying, timestamp with time zone, integer, character varying, integer, character varying, character varying, character varying, character varying, character varying, character, character, character varying, boolean, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs__add_user(integer, character varying, timestamp with time zone, integer, character varying, integer, character varying, character varying, character varying, character varying, character varying, character, character, character varying, boolean, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    p_user_id              alias for $1;  -- default null    
    p_object_type          alias for $2;  -- default 'user'
    p_creation_date        alias for $3;  -- default now()
    p_creation_user        alias for $4;  -- default null
    p_creation_ip          alias for $5;  -- default null
    p_authority_id         alias for $6;  -- defaults to local authority
    p_username             alias for $7;  --
    p_email                alias for $8;  
    p_url                  alias for $9;  -- default null
    p_first_names          alias for $10;  
    p_last_name            alias for $11;  
    p_password             alias for $12; 
    p_salt                 alias for $13; 
    p_screen_name          alias for $14; -- default null
    p_email_verified_p     alias for $15; -- default 't'
    p_member_state         alias for $16; -- default 'approved'
    v_user_id              users.user_id%TYPE;
    v_rel_id               membership_rels.rel_id%TYPE;
begin
    v_user_id := acs_user__new (
        p_user_id, 
        p_object_type, 
        p_creation_date,
        p_creation_user, 
        p_creation_ip, 
        p_authority_id,
        p_username,
        p_email,
        p_url, 
        p_first_names, 
        p_last_name, 
        p_password,
	p_salt, 
        p_screen_name, 
        p_email_verified_p,
        null                  -- context_id
    );
   
    v_rel_id := membership_rel__new (
      null,
      'membership_rel',
      acs__magic_object_id('registered_users'),      
      v_user_id,
      p_member_state,
      null,
      null);

    PERFORM acs_permission__grant_permission (
      v_user_id,
      v_user_id,
      'read'
      );

    PERFORM acs_permission__grant_permission (
      v_user_id,
      v_user_id,
      'write'
      );

    return v_user_id;
   
end;$_$;


ALTER FUNCTION public.acs__add_user(integer, character varying, timestamp with time zone, integer, character varying, integer, character varying, character varying, character varying, character varying, character varying, character, character, character varying, boolean, character varying) OWNER TO simone;

--
-- Name: acs__magic_object_id(character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs__magic_object_id(character varying) RETURNS integer
    LANGUAGE plpgsql STABLE STRICT
    AS $_$
declare
  magic_object_id__name                   alias for $1;  
begin
    return object_id
    from acs_magic_objects
    where name = magic_object_id__name;
end;$_$;


ALTER FUNCTION public.acs__magic_object_id(character varying) OWNER TO simone;

--
-- Name: acs__remove_user(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs__remove_user(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
  remove_user__user_id                alias for $1;  
  v_rec           record;
begin
    delete
    from acs_permissions
    where grantee_id = remove_user__user_id;

    for v_rec in select rel_id
                 from acs_rels
                 where object_id_two = remove_user__user_id
    loop
        perform acs_rel__delete(v_rec.rel_id);
    end loop;

    perform acs_user__delete(remove_user__user_id);

    return 0; 
end;$_$;


ALTER FUNCTION public.acs__remove_user(integer) OWNER TO simone;

