--
-- Name: acs_event__activity_set(integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_event__activity_set(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
        activity_set__event_id        alias for $1;
        activity_set__activity_id     alias for $2;
begin
        update acs_events
        set    activity_id = activity_set__activity_id
        where  event_id    = activity_set__event_id;

	return 0;

end;$_$;


ALTER FUNCTION public.acs_event__activity_set(integer, integer) OWNER TO simone;

--
-- Name: acs_event__delete(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_event__delete(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
       delete__event_id	alias for $1;
       v_recurrence_id		acs_events.recurrence_id%TYPE;
begin
       select recurrence_id into v_recurrence_id
       from   acs_events
       where  event_id = delete__event_id;

       -- acs_events and acs_event_party_map deleted via on delete cascade
       PERFORM acs_object__delete(delete__event_id); 

       -- Check for no more instances and delete recurrence if exists
       if not acs_event__instances_exist_p(v_recurrence_id) then 
            PERFORM recurrence__delete(v_recurrence_id);
       end if;

       return 0;

end;$_$;


ALTER FUNCTION public.acs_event__delete(integer) OWNER TO simone;

--
-- Name: acs_event__delete_all(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_event__delete_all(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
       delete_all__event_id	alias for $1;
       v_recurrence_id		acs_events.recurrence_id%TYPE;
begin

       select recurrence_id into v_recurrence_id
       from   acs_events
       where  event_id = delete_all__event_id;

       PERFORM acs_event__delete_all_recurrences(v_recurrence_id);

       return 0;

end;$_$;


ALTER FUNCTION public.acs_event__delete_all(integer) OWNER TO simone;

--
-- Name: acs_event__delete_all_recurrences(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_event__delete_all_recurrences(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
       delete_all_recurrences__recurrence_id	alias for $1; -- default null
       rec_event				record;
begin
       if delete_all_recurrences__recurrence_id is not null then
            for rec_event in 
	      select event_id 
	      from acs_events 
	      where  recurrence_id = delete_all_recurrences__recurrence_id
	    loop
                PERFORM acs_event__delete(rec_event.event_id);
            end loop;
       end if;

       return 0;

end;$_$;


ALTER FUNCTION public.acs_event__delete_all_recurrences(integer) OWNER TO simone;

--
-- Name: acs_event__get_description(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_event__get_description(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$	-- acs_events.description%TYPE
declare
       get_description__event_id   alias for $1;
       v_description		    acs_events.description%TYPE; 
begin

       select coalesce(e.description, a.description) into v_description
       from   acs_events e
       left join acs_activities a
       on  (e.activity_id = a.activity_id)
       where  e.event_id = get_description__event_id;

       return v_description;

end;$_$;


