--
-- Name: acs_message__first_ancestor(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_message__first_ancestor(integer) RETURNS integer
    LANGUAGE plpgsql STABLE STRICT
    AS $_$
declare
    p_message_id alias for $1;
    v_message_id acs_messages.message_id%TYPE;
    v_ancestor_sk varbit;
begin
    select tree_ancestor_key(tree_sortkey, 1) into v_ancestor_sk
      from acs_messages
     where message_id = p_message_id;

    select message_id into v_message_id
      from acs_messages
     where tree_sortkey = v_ancestor_sk;

    return v_message_id;
end;$_$;


ALTER FUNCTION public.acs_message__first_ancestor(integer) OWNER TO simone;

--
-- Name: acs_message__message_p(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_message__message_p(integer) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $_$
declare
    p_message_id          alias for $1;
    v_check_message_id  integer;
begin
    select count(message_id) into v_check_message_id
        from acs_messages where message_id = p_message_id;

    if v_check_message_id <> 0 then
        return 't';
    else
        return 'f';
    end if;
end;$_$;


