--
-- Name: acs_message__new(integer, integer, timestamp with time zone, integer, character varying, character varying, character varying, character varying, text, integer, integer, integer, integer, character varying, character varying, boolean); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_message__new(integer, integer, timestamp with time zone, integer, character varying, character varying, character varying, character varying, text, integer, integer, integer, integer, character varying, character varying, boolean) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
        p_message_id    alias for $1;  --default null,
        p_reply_to      alias for $2;  --default null,
        p_sent_date     alias for $3;  --default sysdate,
        p_sender        alias for $4;  --default null,
        p_rfc822_id     alias for $5;  --default null,
        p_title         alias for $6;  --default null,
        p_description   alias for $7;  --default null,
        p_mime_type     alias for $8;  --default 'text/plain',
        p_text          alias for $9;  --default null,
        p_data          alias for $10; --default null,
        p_parent_id     alias for $11; --default 0,
        p_context_id    alias for $12;
        p_creation_date timestamptz := current_timestamp;  -- alias for $13 --default sysdate,
        p_creation_user alias for $13; --default null,
        p_creation_ip   alias for $14; --default null,
        p_object_type   alias for $15; --default 'acs_message',
        p_is_live       alias for $16; --default 't'
begin
    return acs_message__new (p_message_id,
                             p_reply_to,
                             p_sent_date,
                             p_sender,
                             p_rfc822_id,
                             p_title,
                             p_description,
                             p_mime_type,
                             p_text,
                             p_data,
                             p_parent_id,
                             p_context_id,
                             p_creation_user,
                             p_creation_ip,
                             p_object_type,
                             p_is_live,
                             null::integer
   );
end;$_$;


ALTER FUNCTION public.acs_message__new(integer, integer, timestamp with time zone, integer, character varying, character varying, character varying, character varying, text, integer, integer, integer, integer, character varying, character varying, boolean) OWNER TO simone;

--
-- Name: acs_message__new(integer, integer, timestamp with time zone, integer, character varying, character varying, character varying, character varying, text, integer, integer, integer, integer, character varying, character varying, boolean, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_message__new(p_message_id integer, p_reply_to integer, p_sent_date timestamp with time zone, p_sender integer, p_rfc822_id character varying, p_title character varying, p_description character varying, p_mime_type character varying, p_text text, p_data integer, p_parent_id integer, p_context_id integer, p_creation_user integer, p_creation_ip character varying, p_object_type character varying, p_is_live boolean, p_package_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
        p_creation_date timestamptz := current_timestamp;  -- alias for $13 --default sysdate,
        v_message_id   acs_messages.message_id%TYPE;
        v_rfc822_id    acs_messages.rfc822_id%TYPE;
        v_revision_id  cr_revisions.revision_id%TYPE;
		v_system_url   varchar;
		v_domain_name  varchar;
		v_idx		   integer;
    BEGIN
        -- generate a message id now so we can get an rfc822 message-id
        if p_message_id is null then
            select nextval('t_acs_object_id_seq') into v_message_id;
        else
            v_message_id := p_message_id;
        end if;

        -- need to make this mandatory also - jg
        -- this needs to be fixed up, but Oracle doesn't give us a way
        -- to get the FQDN

	-- vk: get SystemURL parameter and use it to extract domain name
         select apm__get_value(package_id, 'SystemURL') into v_system_url
          from apm_packages where package_key='acs-kernel';
		v_idx := position('http://' in v_system_url);
		v_domain_name := trim (substr(v_system_url, v_idx + 7));

        if p_rfc822_id is null then
           v_rfc822_id := current_date || '.' || v_message_id || '@' ||
               v_domain_name || '.hate';
        else
            v_rfc822_id := p_rfc822_id;
        end if;

        v_message_id := content_item__new (
            v_rfc822_id,			  -- name           
            p_parent_id,			  -- parent_id      
            p_message_id,			  -- item_id        
            null,				  -- locale
            p_creation_date,			  -- creation_date  
            p_creation_user,			  -- creation_user  
            p_context_id,			  -- context_id     
            p_creation_ip,			  -- creation_ip    
            p_object_type,			  -- item_subtype   
            'acs_message_revision',		  -- content_type   
            null,				  -- title
            null,				  -- description
            'text/plain',			  -- mime_type
            null,				  -- nls_language
            null,				  -- text
            'text',				  -- storage_type
            p_package_id
        );

        insert into acs_messages 
            (message_id, reply_to, sent_date, sender, rfc822_id)
        values 
            (v_message_id, p_reply_to, p_sent_date, p_sender, v_rfc822_id);

        -- create an initial revision for the new message
        v_revision_id := acs_message__edit (
            v_message_id,			   -- message_id     
            p_title,				   -- title          
            p_description,			   -- description    
            p_mime_type,			   -- mime_type      
            p_text,				   -- text           
            p_data,				   -- data           
            p_creation_date,			   -- creation_date  
            p_creation_user,			   -- creation_user  
            p_creation_ip,			   -- creation_ip    
            p_is_live				   -- is_live        
        );

        return v_message_id;
END;
$_$;


ALTER FUNCTION public.acs_message__new(p_message_id integer, p_reply_to integer, p_sent_date timestamp with time zone, p_sender integer, p_rfc822_id character varying, p_title character varying, p_description character varying, p_mime_type character varying, p_text text, p_data integer, p_parent_id integer, p_context_id integer, p_creation_user integer, p_creation_ip character varying, p_object_type character varying, p_is_live boolean, p_package_id integer) OWNER TO simone;

