-- Name: acs_object_util__object_type_exist_p(character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_object_util__object_type_exist_p(character varying) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $_$
declare
    p_object_type       alias for $1;
    v_exist_p           boolean := 't';
begin


    select (case when count(*)=1 then 't' else 'f' end) into v_exist_p
    from   acs_object_types 
    where  object_type = p_object_type;
 
    return v_exist_p;
end;$_$;


