  drop_type__rel_type               alias for $1;  
  drop_type__cascade_p              alias for $2;  -- default 'f'  
  v_cascade_p                       boolean;
begin
    -- XXX do cascade_p.
    -- JCD: cascade_p seems to be ignored in acs_o_type__drop_type anyway...

