--
-- Name: acs_sc_binding__exists_p(character varying, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_sc_binding__exists_p(character varying, character varying) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $_$
declare
    p_contract_name             alias for $1;
    p_impl_name                 alias for $2;
    v_contract_id               integer;
    v_impl_id                   integer;
    v_exists_p                  integer;
begin

    v_contract_id := acs_sc_contract__get_id(p_contract_name);

    v_impl_id := acs_sc_impl__get_id(p_contract_name,p_impl_name);

    select case when count(*)=0 then 0 else 1 end into v_exists_p
    from acs_sc_bindings
    where contract_id = v_contract_id
    and impl_id = v_impl_id;

    return v_exists_p;

end;$_$;


ALTER FUNCTION public.acs_sc_binding__exists_p(character varying, character varying) OWNER TO simone;

--
-- Name: acs_sc_binding__new(integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_sc_binding__new(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    p_contract_id               alias for $1;
    p_impl_id                   alias for $2;
    v_contract_name             varchar;
    v_impl_name                 varchar;
    v_count                     integer;
    v_missing_op                varchar;
begin

    v_contract_name := acs_sc_contract__get_name(p_contract_id);
    v_impl_name := acs_sc_impl__get_name(p_impl_id);

    select count(*),min(operation_name) into v_count, v_missing_op
    from acs_sc_operations
    where contract_id = p_contract_id
    and operation_name not in (select impl_operation_name
                               from acs_sc_impl_aliases
                               where impl_contract_name = v_contract_name
                               and impl_id = p_impl_id);

    if v_count > 0 then
        raise exception 'Binding of % to % failed since certain operations are not implemented like: %.', v_contract_name, v_impl_name, v_missing_op;
    end if;

    insert into acs_sc_bindings (
        contract_id,
        impl_id
    ) values (
        p_contract_id,
        p_impl_id
    );

    return 0;

end;$_$;


ALTER FUNCTION public.acs_sc_binding__new(integer, integer) OWNER TO simone;

--
-- Name: acs_sc_binding__new(character varying, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_sc_binding__new(character varying, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    p_contract_name             alias for $1;
    p_impl_name                 alias for $2;
    v_contract_id               integer;
    v_impl_id                   integer;
    v_count                     integer;
begin

    v_contract_id := acs_sc_contract__get_id(p_contract_name);

    v_impl_id := acs_sc_impl__get_id(p_contract_name,p_impl_name);

    if v_contract_id is null or v_impl_id is null then
        raise exception 'Binding of % to % failed.', p_contract_name, p_impl_name;
    else
        perform acs_sc_binding__new(v_contract_id,v_impl_id);
    end if;

    return 0;

end;$_$;


