-- Name: acs_sc_impl_alias__delete(character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.acs_sc_impl_alias__delete(character varying, character varying, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    p_impl_contract_name        alias for $1;
    p_impl_name                 alias for $2;
    p_impl_operation_name       alias for $3;
    v_impl_id                   integer;
begin

    v_impl_id := acs_sc_impl__get_id(p_impl_contract_name, p_impl_name);

    delete from acs_sc_impl_aliases 
    where impl_contract_name = p_impl_contract_name 
