--

CREATE FUNCTION public.ah_history_party_name(integer, date) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
declare

  p_party_id               alias for $1;  
  p_end_date               alias for $2;

  v_party_name             varchar(1000);

begin

      select party_name into v_party_name              
      from mis_party_mod
      where end_date > p_end_date and 
            party_id = p_party_id
      order by end_date 
      limit 1;

    return v_party_name;

end;$_$;


