--
-- Name: ah_net_price(numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.ah_net_price(numeric, numeric, numeric, numeric) RETURNS numeric
    LANGUAGE plpgsql
    AS $_$
declare
   v_price      alias for $1;
   v_dsc1       alias for $2;
   v_dsc2       alias for $3;
   v_dsc3       alias for $4;

   price      numeric(17, 5);
   dsc1       numeric(5, 2);
   dsc2       numeric(5, 2);
   dsc3       numeric(5, 2);

   net_price  numeric(17, 5);

begin

   price := v_price;

   if v_dsc1 is null 
   then
      dsc1 := 0.00;
   else
      dsc1 := v_dsc1;
   end if;
   if v_dsc2 is null 
   then
      dsc2 := 0.00;
   else
      dsc2 := v_dsc2;
   end if;
   if v_dsc3 is null 
   then
      dsc3 := 0.00;
   else
      dsc3 := v_dsc3;
   end if;
   net_price := ((price - price * dsc1 / 100) - (price - price * dsc1 / 100) * dsc2 / 100) - ((price - price * dsc1 / 100) - (price - price * dsc1 / 100) * dsc2 / 100) * dsc3 /100; 

   return net_price;

end;$_$;


ALTER FUNCTION public.ah_net_price(numeric, numeric, numeric, numeric) OWNER TO simone;

--
-- Name: ah_replace(character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.ah_replace(character varying, character varying, character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
declare
    string      alias for $1;
    sub         alias for $2;
    replacement alias for $3;
    -- xxxxxxxxxxx[MATCH]xxxxxxxxxxxx
    --           | end_before
    --                   | start_after
    match integer;
    end_before integer;
    start_after integer;
    string_replaced varchar;
    string_remainder varchar;
begin
    string_remainder := string;
    string_replaced := '';
    match := position(sub in string_remainder);

    while match > 0 loop
        end_before := match - 1;
        start_after := match + length(sub);
        string_replaced := string_replaced || substr(string_remainder, 1, end_before) || replacement;
        string_remainder := substr(string_remainder, start_after);
        match := position(sub in string_remainder);
    end loop;
    string_replaced := string_replaced || string_remainder;

    return string_replaced;
end;
$_$;


