-- Name: as_assessments; Type: TABLE; Schema: public; Owner: simone
--

CREATE TABLE public.as_assessments (
    assessment_id integer NOT NULL,
    creator_id integer,
    instructions text,
    run_mode character varying(25),
    anonymous_p character(1) DEFAULT 'f'::bpchar,
    secure_access_p character(1) DEFAULT 'f'::bpchar,
    reuse_responses_p character(1) DEFAULT 'f'::bpchar,
    show_item_name_p character(1) DEFAULT 'f'::bpchar,
    random_p character(1) DEFAULT 't'::bpchar,
    entry_page character varying(200),
    exit_page character varying(200),
    consent_page text,
    return_url character varying(200),
    start_time timestamp with time zone,
    end_time timestamp with time zone,
    number_tries integer,
    wait_between_tries integer,
    time_for_response integer,
    ip_mask character varying(100),
    password character varying(100),
    show_feedback character varying(50) DEFAULT 'all'::character varying,
    section_navigation character varying(50) DEFAULT 'default path'::character varying,
    survey_p character(1) DEFAULT 'f'::bpchar,
    type character varying(1000),
    CONSTRAINT as_assessments_anonymous_p_ck CHECK ((anonymous_p = ANY (ARRAY['t'::bpchar, 'f'::bpchar]))),
    CONSTRAINT as_assessments_random_p_ck CHECK ((random_p = ANY (ARRAY['t'::bpchar, 'f'::bpchar]))),
    CONSTRAINT as_assessments_reuse_responses_p_ck CHECK ((reuse_responses_p = ANY (ARRAY['t'::bpchar, 'f'::bpchar]))),
    CONSTRAINT as_assessments_section_navigation_ck CHECK (((section_navigation)::text = ANY (ARRAY[('default path'::character varying)::text, ('randomized'::character varying)::text, ('rule-based branching'::character varying)::text]))),
    CONSTRAINT as_assessments_secure_access_p_ck CHECK ((secure_access_p = ANY (ARRAY['t'::bpchar, 'f'::bpchar]))),
    CONSTRAINT as_assessments_show_feedback_ck CHECK (((show_feedback)::text = ANY (ARRAY[('none'::character varying)::text, ('all'::character varying)::text, ('incorrect'::character varying)::text, ('correct'::character varying)::text]))),
    CONSTRAINT as_assessments_show_item_name_p_ck CHECK ((show_item_name_p = ANY (ARRAY['t'::bpchar, 'f'::bpchar]))),
    CONSTRAINT as_assessments_survey_p_ck CHECK ((survey_p = ANY (ARRAY['t'::bpchar, 'f'::bpchar])))
);


