-- Name: cr_revisions; Type: TABLE; Schema: public; Owner: simone
--

CREATE TABLE public.cr_revisions (
    revision_id integer NOT NULL,
    item_id integer NOT NULL,
    title character varying(1000),
    description text,
    publish_date timestamp with time zone,
    mime_type character varying(200) DEFAULT 'text/plain'::character varying,
    nls_language character varying(50),
    lob integer,
    content text,
    content_length integer
);


ALTER TABLE public.cr_revisions OWNER TO simone;

--
-- Name: TABLE cr_revisions; Type: COMMENT; Schema: public; Owner: simone
--

COMMENT ON TABLE public.cr_revisions IS '
  Each content item may be associated with any number of revisions.
  The item_id is used to associate revisions with an item.
';


--
-- Name: COLUMN cr_revisions.nls_language; Type: COMMENT; Schema: public; Owner: simone
--

COMMENT ON COLUMN public.cr_revisions.nls_language IS '
  NLS_LANGUAGE is required in the same table as the content column
  for multi-lingual searching in Intermedia.
';


--
-- Name: cr_text; Type: TABLE; Schema: public; Owner: simone
--

CREATE TABLE public.cr_text (
    text_data text
);


ALTER TABLE public.cr_text OWNER TO simone;

--
-- Name: TABLE cr_text; Type: COMMENT; Schema: public; Owner: simone
--

COMMENT ON TABLE public.cr_text IS '
  A simple placeholder table for generating input views, so that a
  complete revision may be added with a single INSERT statement.
';


--
-- Name: as_assessmentsi; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.as_assessmentsi AS
 SELECT acs_objects.object_id,
    acs_objects.object_type,
    acs_objects.title AS object_title,
    acs_objects.package_id AS object_package_id,
    acs_objects.context_id,
    acs_objects.security_inherit_p,
    acs_objects.creation_user,
    acs_objects.creation_date,
    acs_objects.creation_ip,
    acs_objects.last_modified,
    acs_objects.modifying_user,
    acs_objects.modifying_ip,
    acs_objects.tree_sortkey,
    acs_objects.max_child_sortkey,
    cr.revision_id,
    cr.title,
    cr.item_id,
    public.content_revision__get_content(cr.revision_id) AS data,
    cr_text.text_data AS text,
    cr.description,
    cr.publish_date,
    cr.mime_type,
    cr.nls_language,
    as_assessments.assessment_id,
    as_assessments.creator_id,
    as_assessments.instructions,
    as_assessments.run_mode,
    as_assessments.anonymous_p,
    as_assessments.secure_access_p,
    as_assessments.reuse_responses_p,
    as_assessments.show_item_name_p,
    as_assessments.random_p,
    as_assessments.entry_page,
    as_assessments.exit_page,
    as_assessments.consent_page,
    as_assessments.return_url,
    as_assessments.start_time,
    as_assessments.end_time,
    as_assessments.number_tries,
    as_assessments.wait_between_tries,
    as_assessments.time_for_response,
    as_assessments.ip_mask,
    as_assessments.password,
    as_assessments.show_feedback,
    as_assessments.section_navigation,
    as_assessments.survey_p,
    as_assessments.type
   FROM public.acs_objects,
    public.cr_revisions cr,
    public.cr_text,
    public.as_assessments
  WHERE ((acs_objects.object_id = cr.revision_id) AND (acs_objects.object_id = as_assessments.assessment_id));


ALTER TABLE public.as_assessmentsi OWNER TO simone;

--
-- Name: as_assessments_f(public.as_assessmentsi); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.as_assessments_f(p_new public.as_assessmentsi) RETURNS void
    LANGUAGE plpgsql
    AS $$
             declare
               v_revision_id integer;
             begin

               select content_revision__new(
                                     p_new.title,
                                     p_new.description,
                                     now(),
                                     p_new.mime_type,
                                     p_new.nls_language,
                                     case when p_new.text is null 
                                              then p_new.data 
                                              else p_new.text
                                           end,
                                     content_symlink__resolve(p_new.item_id),
                                     p_new.revision_id,
                                     now(),
                                     p_new.creation_user, 
                                     p_new.creation_ip,
                                     p_new.object_package_id
                ) into v_revision_id;
                 insert into as_assessments ( assessment_id, type, section_navigation, show_feedback, password, ip_mask, time_for_response, wait_between_tries, number_tries, end_time, start_time, return_url, consent_page, exit_page, entry_page, random_p, show_item_name_p, reuse_responses_p, secure_access_p, anonymous_p, run_mode, instructions, creator_id ) values (v_revision_id, p_new.type, p_new.section_navigation, p_new.show_feedback, p_new.password, p_new.ip_mask, p_new.time_for_response, p_new.wait_between_tries, p_new.number_tries, p_new.end_time, p_new.start_time, p_new.return_url, p_new.consent_page, p_new.exit_page, p_new.entry_page, p_new.random_p, p_new.show_item_name_p, p_new.reuse_responses_p, p_new.secure_access_p, p_new.anonymous_p, p_new.run_mode, p_new.instructions, p_new.creator_id);
    
   return;
   end;$$;


ALTER FUNCTION public.as_assessments_f(p_new public.as_assessmentsi) OWNER TO simone;

--
-- Name: as_inter_item_check__delete(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.as_inter_item_check__delete(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare 
	del__inter_item_check_id     alias for $1;
begin
	delete from as_actions_log where 
	inter_item_check_id = del__inter_item_check_id;
	
        delete from as_param_map where inter_item_check_id= del__inter_item_check_id;

	delete from as_action_map where inter_item_check_id = del__inter_item_check_id;

	delete from as_inter_item_checks where inter_item_check_id = del__inter_item_check_id;
        PERFORM acs_object__delete (del__inter_item_check_id);	
	return del__inter_item_check_id;	

end;$_$;


ALTER FUNCTION public.as_inter_item_check__delete(integer) OWNER TO simone;

--
-- Name: as_inter_item_check__new(integer, boolean, integer, integer, character varying, character varying, character varying, boolean, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.as_inter_item_check__new(integer, boolean, integer, integer, character varying, character varying, character varying, boolean, integer, integer, integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare 
	new__inter_item_check_id     alias for $1;
        new__action_p                alias for $2;
        new__section_id_from         alias for $3;
        new__section_id_to           alias for $4;
        new__check_sql               alias for $5;
        new__name	  	     alias for $6;
        new__description	     alias for $7;
        new__postcheck_p	     alias for $8;
        new__item_id                 alias for $9;
	new__creation_user           alias for $10; 
	new__context_id              alias for $11;
	new__assessment_id	     alias for $12; 
	v_inter_item_check_id	     integer;
begin
	v_inter_item_check_id := acs_object__new (
		new__inter_item_check_id,
		'as_inter_item_check',
		now(),
		new__creation_user,
		null,
		new__context_id
	);
	insert into as_inter_item_checks 
	(inter_item_check_id,action_p,section_id_from,section_id_to,check_sql,name,description,postcheck_p,item_id,assessment_id)
        values (v_inter_item_check_id,new__action_p,new__section_id_from,new__section_id_to,new__check_sql,new__name,new__description,new__postcheck_p,new__item_id,new__assessment_id);

         return v_inter_item_check_id;
end;$_$;


ALTER FUNCTION public.as_inter_item_check__new(integer, boolean, integer, integer, character varying, character varying, character varying, boolean, integer, integer, integer, integer) OWNER TO simone;

