--
-- Name: as_sessions; Type: TABLE; Schema: public; Owner: simone
--

CREATE TABLE public.as_sessions (
    session_id integer NOT NULL,
    assessment_id integer,
    subject_id integer,
    staff_id integer,
    target_datetime timestamp with time zone,
    creation_datetime timestamp with time zone,
    first_mod_datetime timestamp with time zone,
    last_mod_datetime timestamp with time zone,
    completed_datetime timestamp with time zone,
    session_status character varying(20),
    assessment_status character varying(20),
    percent_score integer,
    CONSTRAINT as_sessions_percent_score_ck CHECK ((percent_score <= 100))
);


ALTER TABLE public.as_sessions OWNER TO simone;

--
-- Name: as_sessionsi; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.as_sessionsi AS
 SELECT acs_objects.object_id,
    acs_objects.object_type,
    acs_objects.title AS object_title,
    acs_objects.package_id AS object_package_id,
    acs_objects.context_id,
    acs_objects.security_inherit_p,
    acs_objects.creation_user,
    acs_objects.creation_date,
    acs_objects.creation_ip,
    acs_objects.last_modified,
    acs_objects.modifying_user,
    acs_objects.modifying_ip,
    acs_objects.tree_sortkey,
    acs_objects.max_child_sortkey,
    cr.revision_id,
    cr.title,
    cr.item_id,
    public.content_revision__get_content(cr.revision_id) AS data,
    cr_text.text_data AS text,
    cr.description,
    cr.publish_date,
    cr.mime_type,
    cr.nls_language,
    as_sessions.session_id,
    as_sessions.assessment_id,
    as_sessions.subject_id,
    as_sessions.staff_id,
    as_sessions.target_datetime,
    as_sessions.creation_datetime,
    as_sessions.first_mod_datetime,
    as_sessions.last_mod_datetime,
    as_sessions.completed_datetime,
    as_sessions.session_status,
    as_sessions.assessment_status,
    as_sessions.percent_score
   FROM public.acs_objects,
    public.cr_revisions cr,
    public.cr_text,
    public.as_sessions
  WHERE ((acs_objects.object_id = cr.revision_id) AND (acs_objects.object_id = as_sessions.session_id));


ALTER TABLE public.as_sessionsi OWNER TO simone;

--
-- Name: as_sessions_f(public.as_sessionsi); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.as_sessions_f(p_new public.as_sessionsi) RETURNS void
    LANGUAGE plpgsql
    AS $$
             declare
               v_revision_id integer;
             begin

               select content_revision__new(
                                     p_new.title,
                                     p_new.description,
                                     now(),
                                     p_new.mime_type,
                                     p_new.nls_language,
                                     case when p_new.text is null 
                                              then p_new.data 
                                              else p_new.text
                                           end,
                                     content_symlink__resolve(p_new.item_id),
                                     p_new.revision_id,
                                     now(),
                                     p_new.creation_user, 
                                     p_new.creation_ip,
                                     p_new.object_package_id
                ) into v_revision_id;
                 insert into as_sessions ( session_id, percent_score, assessment_status, session_status, completed_datetime, last_mod_datetime, first_mod_datetime, creation_datetime, target_datetime, staff_id, subject_id, assessment_id ) values (v_revision_id, p_new.percent_score, p_new.assessment_status, p_new.session_status, p_new.completed_datetime, p_new.last_mod_datetime, p_new.first_mod_datetime, p_new.creation_datetime, p_new.target_datetime, p_new.staff_id, p_new.subject_id, p_new.assessment_id);
    
   return;
   end;$$;


