-- Name: cal_item__delete_all(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.cal_item__delete_all(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    delete__recurrence_id		alias for $1;
    v_event                             RECORD;
begin
    for v_event in 
	select event_id from acs_events
        where recurrence_id= delete__recurrence_id
    LOOP
        PERFORM cal_item__delete(v_event.event_id);
    END LOOP;

    PERFORM recurrence__delete(delete__recurrence_id);

    return 0;

end;$_$;


