-- Name: category_synonym__edit(integer, character varying, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.category_synonym__edit(integer, character varying, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
	p_synonym_id	alias for $1;
	p_new_name	alias for $2;
	p_locale	alias for $3;
begin
	-- update synonym data
	update	category_synonyms
	set	name = p_new_name,
		locale = p_locale
	where	synonym_id = p_synonym_id;

	-- update synonym index and search results
	PERFORM category_synonym__reindex (p_synonym_id, p_new_name, p_locale);

	return (p_synonym_id);
end;$_$;


