--
-- Name: category_tree__new(integer, character varying, character varying, character varying, character, timestamp with time zone, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.category_tree__new(integer, character varying, character varying, character varying, character, timestamp with time zone, integer, character varying, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    p_tree_id               alias for $1;
    p_locale                alias for $2;
    p_tree_name             alias for $3;
    p_description           alias for $4;
    p_site_wide_p           alias for $5;
    p_creation_date         alias for $6;
    p_creation_user         alias for $7;
    p_creation_ip           alias for $8;
    p_context_id            alias for $9;
  
    v_tree_id               integer;
begin
	v_tree_id := acs_object__new (
		p_tree_id,         -- object_id
		'category_tree', -- object_type
		p_creation_date,   -- creation_date
		p_creation_user,   -- creation_user
		p_creation_ip,     -- creation_ip
		p_context_id,      -- context_id
                p_tree_name,       -- title
                null               -- package_id
	);

	insert into category_trees
	   (tree_id, site_wide_p)
	values
	   (v_tree_id, p_site_wide_p);

	perform acs_permission__grant_permission (
		v_tree_id,             -- object_id
		p_creation_user,       -- grantee_id
		'category_tree_read' -- privilege
	);
	perform acs_permission__grant_permission (
		v_tree_id,                -- object_id
		p_creation_user,          -- grantee_id
		'category_tree_write'   -- privilege
	);
	perform acs_permission__grant_permission (
		v_tree_id,                          -- object_id
		p_creation_user,                    -- grantee_id
		'category_tree_grant_permissions' -- privilege
	);

	insert into category_tree_translations
	    (tree_id, locale, name, description)
	values
	    (v_tree_id, p_locale, p_tree_name, p_description);

	return v_tree_id;
end;
$_$;


ALTER FUNCTION public.category_tree__new(integer, character varying, character varying, character varying, character, timestamp with time zone, integer, character varying, integer) OWNER TO simone;

--
-- Name: category_tree__new_translation(integer, character varying, character varying, character varying, timestamp with time zone, integer, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.category_tree__new_translation(integer, character varying, character varying, character varying, timestamp with time zone, integer, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    p_tree_id                alias for $1;
    p_locale                 alias for $2;
    p_tree_name              alias for $3;
    p_description            alias for $4;
    p_modifying_date         alias for $5;
    p_modifying_user         alias for $6;
    p_modifying_ip           alias for $7;
begin
	insert into category_tree_translations
	    (tree_id, locale, name, description)
	values
	    (p_tree_id, p_locale, p_tree_name, p_description);

	update acs_objects
	set last_modified = p_modifying_date,
	    modifying_user = p_modifying_user,
	    modifying_ip = p_modifying_ip
	where object_id = p_tree_id;
        return 0;
end;
$_$;


ALTER FUNCTION public.category_tree__new_translation(integer, character varying, character varying, character varying, timestamp with time zone, integer, character varying) OWNER TO simone;

--
-- Name: category_tree__unmap(integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.category_tree__unmap(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    p_object_id              alias for $1;
    p_tree_id                alias for $2;
begin
	delete from category_tree_map
	where object_id = p_object_id
	and tree_id = p_tree_id;
        return 0;
end;
$_$;


ALTER FUNCTION public.category_tree__unmap(integer, integer) OWNER TO simone;

--
-- Name: cmp_pg_version(character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.cmp_pg_version(p__version character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    pg_version integer[];
    user_pg_version integer[];
    index integer;
    ret_val integer;
    i integer;
BEGIN
    ret_val = 0;

    user_pg_version := string_to_array(trim(p__version),'.')::int[];
    select string_to_array(setting, '.')::int[] into pg_version from pg_settings where name = 'server_version';


    for index in array_length(user_pg_version, 1) + 1..array_length(pg_version, 1) loop
        user_pg_version[index] := 0;
    end loop;

    index := 1;

    while (index <= array_length(pg_version, 1) and ret_val = 0) loop
        if user_pg_version[index] > pg_version[index] then
            ret_val := -1;
    elsif user_pg_version[index] < pg_version[index] then
            ret_val := 1;
        end if;
        index := index + 1;
    end loop;

    return ret_val;
END;

$$;


ALTER FUNCTION public.cmp_pg_version(p__version character varying) OWNER TO simone;

