CREATE FUNCTION public.coimaimp_upper_pr() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
begin
    new.cod_impianto_est := upper(new.cod_impianto_est);
    new.toponimo         := upper(new.toponimo);
    new.indirizzo        := upper(new.indirizzo);
    return new;
end;
$$;


