--
-- Name: composition_rel__new(integer, character varying, integer, integer, integer, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.composition_rel__new(integer, character varying, integer, integer, integer, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
  new__rel_id            alias for $1;  -- default null  
  rel_type               alias for $2;  -- default 'composition_rel'
  object_id_one          alias for $3;  
  object_id_two          alias for $4;  
  creation_user          alias for $5;  -- default null
  creation_ip            alias for $6;  -- default null
  v_rel_id               integer;       
begin
    v_rel_id := acs_rel__new (
      new__rel_id,
      rel_type,
      object_id_one,
      object_id_two,
      object_id_one,
      creation_user,
      creation_ip
    );

    insert into composition_rels
     (rel_id)
    values
     (v_rel_id);

    return v_rel_id;
   
end;$_$;


