--

CREATE FUNCTION public.content_extlink__is_extlink(integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
declare
  is_extlink__item_id                alias for $1;  
  v_extlink_p                        boolean;
begin

  select 
    count(1) = 1 into v_extlink_p
  from 
    cr_extlinks
  where 
    extlink_id = is_extlink__item_id;
  
  return v_extlink_p;
 
end;$_$;


