--
-- Name: content_extlink__new(character varying, character varying, character varying, character varying, integer, integer, timestamp with time zone, integer, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.content_extlink__new(character varying, character varying, character varying, character varying, integer, integer, timestamp with time zone, integer, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
  new__name                   alias for $1;  -- default null  
  new__url                    alias for $2;  
  new__label                  alias for $3;  -- default null
  new__description            alias for $4;  -- default null
  new__parent_id              alias for $5;  
  new__extlink_id             alias for $6;  -- default null
  new__creation_date          alias for $7;  -- default now()
  new__creation_user          alias for $8;  -- default null
  new__creation_ip            alias for $9;  -- default null
begin
  return content_extlink__new(new__name,
                              new__url,
                              new__label,
                              new__description,
                              new__parent_id,
                              new__extlink_id,
                              new__creation_date,
                              new__creation_user,
                              new__creation_ip,
                              null
  );

end;$_$;


ALTER FUNCTION public.content_extlink__new(character varying, character varying, character varying, character varying, integer, integer, timestamp with time zone, integer, character varying) OWNER TO simone;

--
-- Name: content_extlink__new(character varying, character varying, character varying, character varying, integer, integer, timestamp with time zone, integer, character varying, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.content_extlink__new(new__name character varying, new__url character varying, new__label character varying, new__description character varying, new__parent_id integer, new__extlink_id integer, new__creation_date timestamp with time zone, new__creation_user integer, new__creation_ip character varying, new__package_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_extlink_id                cr_extlinks.extlink_id%TYPE;
  v_package_id                acs_objects.package_id%TYPE;
  v_label                     cr_extlinks.label%TYPE;
  v_name                      cr_items.name%TYPE;
BEGIN

  if new__label is null then
    v_label := new__url;
  else
    v_label := new__label;
  end if;

  if new__name is null then
    select nextval('t_acs_object_id_seq') into v_extlink_id from dual;
    v_name := 'link' || v_extlink_id;
  else
    v_name := new__name;
  end if;

  if new__package_id is null then
    v_package_id := acs_object__package_id(new__parent_id);
  else
    v_package_id := new__package_id;
  end if;

  v_extlink_id := content_item__new(
      v_name, 
      new__parent_id,
      new__extlink_id,
      null,
      new__creation_date, 
      new__creation_user, 
      null,
      new__creation_ip, 
      'content_item',
      'content_extlink', 
      null,
      null,
      'text/plain',
      null,
      null,
      'text',
      v_package_id
  );

  insert into cr_extlinks
    (extlink_id, url, label, description)
  values
    (v_extlink_id, new__url, v_label, new__description);

  update acs_objects
  set title = v_label
  where object_id = v_extlink_id;

  return v_extlink_id;

END;
$$;


