--

CREATE FUNCTION public.content_folder__delete(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
  delete__folder_id              alias for $1;  
  v_count                        integer;       
  v_parent_id                    integer;  
  v_path                         varchar;     
begin
	return content_folder__del(
		delete__folder_id,
		'f'
		);
end;$_$;


