--

CREATE TABLE public.content_includelet_revisions (
    content_includelet_revision_id integer NOT NULL
);


ALTER TABLE public.content_includelet_revisions OWNER TO simone;

--
-- Name: content_includelet_revisionsi; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.content_includelet_revisionsi AS
 SELECT acs_objects.object_id,
    acs_objects.object_type,
    acs_objects.title AS object_title,
    acs_objects.package_id AS object_package_id,
    acs_objects.context_id,
    acs_objects.security_inherit_p,
    acs_objects.creation_user,
    acs_objects.creation_date,
    acs_objects.creation_ip,
    acs_objects.last_modified,
    acs_objects.modifying_user,
    acs_objects.modifying_ip,
    acs_objects.tree_sortkey,
    acs_objects.max_child_sortkey,
    cr.revision_id,
    cr.title,
    cr.item_id,
    public.content_revision__get_content(cr.revision_id) AS data,
    cr_text.text_data AS text,
    cr.description,
    cr.publish_date,
    cr.mime_type,
    cr.nls_language,
    content_includelet_revisions.content_includelet_revision_id
   FROM public.acs_objects,
    public.cr_revisions cr,
    public.cr_text,
    public.content_includelet_revisions
  WHERE ((acs_objects.object_id = cr.revision_id) AND (acs_objects.object_id = content_includelet_revisions.content_includelet_revision_id));


ALTER TABLE public.content_includelet_revisionsi OWNER TO simone;

--
-- Name: content_includelet_revisions_f(public.content_includelet_revisionsi); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.content_includelet_revisions_f(p_new public.content_includelet_revisionsi) RETURNS void
    LANGUAGE plpgsql
    AS $$
             declare
               v_revision_id integer;
             begin

               select content_revision__new(
                                     p_new.title,
                                     p_new.description,
                                     now(),
                                     p_new.mime_type,
                                     p_new.nls_language,
                                     case when p_new.text is null 
                                              then p_new.data 
                                              else p_new.text
                                           end,
                                     content_symlink__resolve(p_new.item_id),
                                     p_new.revision_id,
                                     now(),
                                     p_new.creation_user, 
                                     p_new.creation_ip,
                                     p_new.object_package_id
                ) into v_revision_id;
                 insert into content_includelet_revisions ( content_includelet_revision_id ) values (v_revision_id);
    
   return;
   end;$$;


