--

CREATE TABLE public.cr_news (
    news_id integer NOT NULL,
    lead character varying(4000),
    package_id integer NOT NULL,
    archive_date timestamp with time zone,
    approval_user integer,
    approval_date timestamp with time zone,
    approval_ip character varying(50)
);


ALTER TABLE public.cr_news OWNER TO simone;

--
-- Name: cr_newsi; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.cr_newsi AS
 SELECT acs_objects.object_id,
    acs_objects.object_type,
    acs_objects.title AS object_title,
    acs_objects.package_id AS object_package_id,
    acs_objects.context_id,
    acs_objects.security_inherit_p,
    acs_objects.creation_user,
    acs_objects.creation_date,
    acs_objects.creation_ip,
    acs_objects.last_modified,
    acs_objects.modifying_user,
    acs_objects.modifying_ip,
    acs_objects.tree_sortkey,
    acs_objects.max_child_sortkey,
    cr.revision_id,
    cr.title,
    cr.item_id,
    public.content_revision__get_content(cr.revision_id) AS data,
    cr_text.text_data AS text,
    cr.description,
    cr.publish_date,
    cr.mime_type,
    cr.nls_language,
    cr_news.news_id,
    cr_news.lead,
    cr_news.package_id,
    cr_news.archive_date,
    cr_news.approval_user,
    cr_news.approval_date,
    cr_news.approval_ip
   FROM public.acs_objects,
    public.cr_revisions cr,
    public.cr_text,
    public.cr_news
  WHERE ((acs_objects.object_id = cr.revision_id) AND (acs_objects.object_id = cr_news.news_id));


ALTER TABLE public.cr_newsi OWNER TO simone;

--
-- Name: cr_news_f(public.cr_newsi); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.cr_news_f(p_new public.cr_newsi) RETURNS void
    LANGUAGE plpgsql
    AS $$
             declare
               v_revision_id integer;
             begin

               select content_revision__new(
                                     p_new.title,
                                     p_new.description,
                                     now(),
                                     p_new.mime_type,
                                     p_new.nls_language,
                                     case when p_new.text is null 
                                              then p_new.data 
                                              else p_new.text
                                           end,
                                     content_symlink__resolve(p_new.item_id),
                                     p_new.revision_id,
                                     now(),
                                     p_new.creation_user, 
                                     p_new.creation_ip,
                                     p_new.object_package_id
                ) into v_revision_id;
                 insert into cr_news ( news_id, approval_ip, approval_date, approval_user, archive_date, lead ) values (v_revision_id, p_new.approval_ip, p_new.approval_date, p_new.approval_user, p_new.archive_date, p_new.lead);
    
   return;
   end;$$;


ALTER FUNCTION public.cr_news_f(p_new public.cr_newsi) OWNER TO simone;

--
-- Name: cr_revision_del_rev_ri_tr(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.cr_revision_del_rev_ri_tr() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
        dummy           integer;
BEGIN
        select 1 into dummy
        from 
          cr_items
        where 
          item_id = old.item_id
        and
          live_revision = old.revision_id;
        
        if FOUND then
          raise EXCEPTION 'Referential Integrity: attempting to delete live_revision: %', old.revision_id;
        end if;
        
        select 1 into dummy
        from 
          cr_items
        where 
          item_id = old.item_id
        and
          latest_revision = old.revision_id;
        
        if FOUND then
          raise EXCEPTION 'Referential Integrity: attempting to delete latest_revision: %', old.revision_id;
        end if;
        
        return old;
END;
$$;


ALTER FUNCTION public.cr_revision_del_rev_ri_tr() OWNER TO simone;

--
-- Name: cr_revision_del_ri_tr(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.cr_revision_del_ri_tr() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
        dummy           integer;
        v_latest        integer;
        v_live          integer;
BEGIN
        select 1 into dummy
        from 
          cr_revisions           
        where 
          revision_id = old.live_revision;
        
        if FOUND then
          raise EXCEPTION 'Referential Integrity: live_revision still exists: %', old.live_revision;
        end if;
        
        select 1 into dummy
        from 
          cr_revisions 
        where 
          revision_id = old.latest_revision;
        
        if FOUND then
          raise EXCEPTION 'Referential Integrity: latest_revision still exists: %', old.latest_revision;
        end if;
        
        return old;
END;
$$;


ALTER FUNCTION public.cr_revision_del_ri_tr() OWNER TO simone;

