-- Name: cr_revision_ins_ri_tr(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.cr_revision_ins_ri_tr() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
        dummy           integer;
        v_latest        integer;
        v_live          integer;
BEGIN
        select 1 into dummy
        from 
          cr_revisions           
        where 
          revision_id = new.live_revision;
        
        if NOT FOUND and new.live_revision is NOT NULL then
          raise EXCEPTION 'Referential Integrity: live_revision does not exist: %', new.live_revision;
        end if;
        
        select 1 into dummy
        from 
          cr_revisions 
        where 
          revision_id = new.latest_revision;
        
        if NOT FOUND and new.latest_revision is NOT NULL then
          raise EXCEPTION 'Referential Integrity: latest_revision does not exist: %', new.latest_revision;
        end if;

        return new;
END;
$$;


ALTER FUNCTION public.cr_revision_ins_ri_tr() OWNER TO simone;

--
-- Name: cr_revision_latest_tr(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.cr_revision_latest_tr() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  update cr_items set latest_revision = new.revision_id
  where item_id = new.item_id;
  return new;
end;$$;


ALTER FUNCTION public.cr_revision_latest_tr() OWNER TO simone;

--
-- Name: cr_revision_up_ri_tr(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.cr_revision_up_ri_tr() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
        dummy           integer;
        v_latest        integer;
        v_live          integer;
BEGIN
        select 1 into dummy
        from 
          cr_revisions           
        where 
          revision_id = new.live_revision;
        
        if NOT FOUND and new.live_revision <> old.live_revision and new.live_revision is NOT NULL then
          raise EXCEPTION 'Referential Integrity: live_revision does not exist: %', new.live_revision;
        end if;
        
        select 1 into dummy
        from 
          cr_revisions 
        where 
          revision_id = new.latest_revision;
        
        if NOT FOUND and new.latest_revision <> old.latest_revision and new.latest_revision is NOT NULL then
          raise EXCEPTION 'Referential Integrity: latest_revision does not exist: %', new.latest_revision;
        end if;
        
        return new;
END;
$$;


ALTER FUNCTION public.cr_revision_up_ri_tr() OWNER TO simone;

--
-- Name: cr_revisionsi; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.cr_revisionsi AS
 SELECT acs_objects.object_id,
    acs_objects.object_type,
    acs_objects.title AS object_title,
    acs_objects.package_id AS object_package_id,
    acs_objects.context_id,
    acs_objects.security_inherit_p,
    acs_objects.creation_user,
    acs_objects.creation_date,
    acs_objects.creation_ip,
    acs_objects.last_modified,
    acs_objects.modifying_user,
    acs_objects.modifying_ip,
    acs_objects.tree_sortkey,
    acs_objects.max_child_sortkey,
    cr.revision_id,
    cr.title,
    cr.item_id,
    public.content_revision__get_content(cr.revision_id) AS data,
    cr_text.text_data AS text,
    cr.description,
    cr.publish_date,
    cr.mime_type,
    cr.nls_language
   FROM public.acs_objects,
    public.cr_revisions cr,
    public.cr_text
  WHERE (acs_objects.object_id = cr.revision_id);


ALTER TABLE public.cr_revisionsi OWNER TO simone;

--
-- Name: cr_revisions_f(public.cr_revisionsi); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.cr_revisions_f(p_new public.cr_revisionsi) RETURNS void
    LANGUAGE plpgsql
    AS $$
             declare
               v_revision_id integer;
             begin

               select content_revision__new(
                                     p_new.title,
                                     p_new.description,
                                     now(),
                                     p_new.mime_type,
                                     p_new.nls_language,
                                     case when p_new.text is null 
                                              then p_new.data 
                                              else p_new.text
                                           end,
                                     content_symlink__resolve(p_new.item_id),
                                     p_new.revision_id,
                                     now(),
                                     p_new.creation_user, 
                                     p_new.creation_ip,
                                     p_new.object_package_id
                ) into v_revision_id;
                
   return;
   end;$$;


ALTER FUNCTION public.cr_revisions_f(p_new public.cr_revisionsi) OWNER TO simone;

--
-- Name: cr_scheduled_release_exec(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.cr_scheduled_release_exec() RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  exec__last_exec             timestamptz;
  exec__this_exec             timestamptz default current_timestamp;
  exec__items_released        integer default 0;
  exec__items_expired         integer default 0;
  exec__err_num               integer;  -- sqlcode
  exec__err_msg               varchar;  -- substr(sqlerrm, 1, 500);
  item_rec                    record;
begin

    select last_exec into exec__last_exec from cr_scheduled_release_job;

    for item_rec in select 
                      p.item_id, live_revision
                    from
                      cr_release_periods p, cr_items i
                    where
                      start_when between exec__last_exec and now()
                    and
                      p.item_id = i.item_id 
    LOOP
      -- update publish status
      update cr_items
	set publish_status = 'live'
      where
	item_id = item_rec.item_id;
      exec__items_released := exec__items_released + 1;
    end loop;

    for item_rec in select 
                      p.item_id, live_revision
                    from
                      cr_release_periods p, cr_items i
                    where
                      end_when between exec__last_exec and now()
                    and
                      p.item_id = i.item_id
    LOOP
      -- update publish status
      update cr_items
	set publish_status = 'expired'
      where
	item_id = item_rec.item_id;

      exec__items_expired := exec__items_expired + 1;

    end loop;

  -- exception

  --   when others then
  --    err_num := SQLCODE;
  --    err_msg := substr(SQLERRM, 1, 500);
  -- end;

  -- keep a record of the update

  insert into cr_scheduled_release_log (
    items_released, items_expired, err_num, err_msg
  ) values (
    exec__items_released, exec__items_expired, exec__err_num, 
    exec__err_msg
  );

  -- Table was growing without bound (OpenACS DanW)
  delete from cr_scheduled_release_log
  where exec_date < now() - '4 week'::interval;

  -- Reset the last time of execution to start of processing
  update cr_scheduled_release_job set last_exec = exec__this_exec;

  return 0;
end;$$;


ALTER FUNCTION public.cr_scheduled_release_exec() OWNER TO simone;

