--
-- Name: dotlrn_community_admin_p(integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.dotlrn_community_admin_p(integer, integer) RETURNS character
    LANGUAGE plpgsql
    AS $_$
  declare 
       p_group_id alias for $1;
       p_party_id alias for $2;
  begin
    --
    -- direct permissions
    if exists (
        select 1
          from acs_object_grantee_priv_map
         where object_id = p_group_id
           and grantee_id =  p_party_id
           and privilege = 'admin')
    then 
        return 't';
    end if;       

    -- check to see if the user belongs to a rel seg that has
    -- the admin priv on the object (in this case a group)


    if exists (
        select 1
        from acs_object_grantee_priv_map ogpm,
          rel_seg_approved_member_map rs
        where rs.group_id = p_group_id
          and ogpm.object_id = rs.group_id
          and ogpm.privilege = 'admin'
          and ogpm.grantee_id = rs.segment_id
          and rs.member_id = p_party_id)
    then
        return 't';
    end if;

    return 'f';
end;$_$;


ALTER FUNCTION public.dotlrn_community_admin_p(integer, integer) OWNER TO simone;

