--
-- Name: dotlrn_privacy__guest_p(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.dotlrn_privacy__guest_p(integer) RETURNS character
    LANGUAGE plpgsql
    AS $_$
declare
  v_user_id alias for $1;
  v_count integer;
  v_guest_p char(1);
begin
  select count(*) into v_count from dotlrn_guest_status where user_id = v_user_id;
  if v_count > 1 then
    raise EXCEPTION '-20000: Guest status is multiply defined for user %', v_user_id;
  end if;
  if v_count = 0 then
    raise EXCEPTION '-20000: Guest status is not defined for user %', v_user_id;
  end if;
  select guest_p into v_guest_p from dotlrn_guest_status where user_id = v_user_id;
  return v_guest_p;
end;$_$;


ALTER FUNCTION public.dotlrn_privacy__guest_p(integer) OWNER TO simone;

