-- Name: dotlrn_privacy__set_user_guest(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.dotlrn_privacy__set_user_guest(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
  v_user_id alias for $1;
  v_rel_id integer;
  cur record;
begin
  for cur in
    select r.rel_id 
      from acs_rels r, 
           membership_rels m 
      where m.rel_id = r.rel_id 
        and (r.rel_type = 'dotlrn_guest_rel'
             or r.rel_type = 'dotlrn_non_guest_rel')
        and r.object_id_one = acs__magic_object_id('registered_users')
        and r.object_id_two = v_user_id
  loop 
    perform membership_rel__delete(cur.rel_id);
  end loop;
  v_rel_id := membership_rel__new(
    null,
    'dotlrn_guest_rel',
    acs__magic_object_id('registered_users'),
    v_user_id,
    'approved',
    null,
    null
  );

  return 0;
end;$_$;


ALTER FUNCTION public.dotlrn_privacy__set_user_guest(integer) OWNER TO simone;

