    evaluation_tasks.points,
    evaluation_tasks.perfect_score,
    evaluation_tasks.relative_weight,
    evaluation_tasks.forums_related_p
   FROM public.acs_objects,
    public.cr_revisions cr,
    public.cr_text,
    public.evaluation_tasks
  WHERE ((acs_objects.object_id = cr.revision_id) AND (acs_objects.object_id = evaluation_tasks.task_id));


