                                     p_new.revision_id,
                                     now(),
                                     p_new.creation_user, 
                                     p_new.creation_ip,
                                     p_new.object_package_id
                ) into v_revision_id;
                 insert into evaluation_tasks ( task_id, forums_related_p, relative_weight, perfect_score, points, requires_grade_p, late_submit_p, online_p, weight, grade_item_id, due_date, number_of_members, task_name, task_item_id ) values (v_revision_id, p_new.forums_related_p, p_new.relative_weight, p_new.perfect_score, p_new.points, p_new.requires_grade_p, p_new.late_submit_p, p_new.online_p, p_new.weight, p_new.grade_item_id, p_new.due_date, p_new.number_of_members, p_new.task_name, p_new.task_item_id);
    
   return;
   end;$$;


