--
-- Name: faq__clone(integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.faq__clone(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
 p_new_package_id  	alias for $1;   --default null,
 p_old_package_id 	alias for $2;   --default null
 v_faq_id 		faqs.faq_id%TYPE;
 one_faq		record;
 entry			record;

begin
            -- get all the faqs belonging to the old package,
            -- and create new faqs for the new package
            for one_faq in select *
                            from acs_objects o, faqs f
                            where o.object_id = f.faq_id
                            and o.context_id = p_old_package_id
            loop
               v_faq_id := faq__new_faq (
                    			one_faq.faq_name,
                    			one_faq.separate_p,
                    			p_new_package_id
               	);

           	for entry in select * from faq_q_and_as
                                   where faq_id = one_faq.faq_id
           	loop

           		perform  faq__new_q_and_a (
                       		entry.faq_id,
                       		v_faq_id,
                       		entry.question,
                       		entry.answer,
                       		entry.sort_key
           	);
               end loop;
           end loop;
 return 0;
 end;
$_$;


ALTER FUNCTION public.faq__clone(integer, integer) OWNER TO simone;

--
-- Name: faq__delete_faq(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.faq__delete_faq(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
	p_faq_id 	alias for $1;
	del_rec record;
begin
	   	-- Because q_and_as are objects, we need to
    	-- loop through a list of them, and call an explicit
    	-- delete function for each one. (i.e. each
    	-- entry_id)
	for del_rec in select entry_id from faq_q_and_as
		where faq_id = p_faq_id
  loop
		PERFORM faq__delete_q_and_a(del_rec.entry_id);
	end loop;

	delete from faqs where faq_id = p_faq_id;

	PERFORM  acs_object__delete(p_faq_id);

	return 0;

end;$_$;


ALTER FUNCTION public.faq__delete_faq(integer) OWNER TO simone;

--
-- Name: faq__delete_q_and_a(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.faq__delete_q_and_a(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
	p_entry_id	alias for $1;
begin
	delete from faq_q_and_as where entry_id =  p_entry_id;
	raise NOTICE 'Deleting FAQ_Q_and_A...';
	PERFORM acs_object__delete(p_entry_id);

	return 0;

end;$_$;


ALTER FUNCTION public.faq__delete_q_and_a(integer) OWNER TO simone;

