--
-- Name: forums_mess_insert_tr(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_mess_insert_tr() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
    v_max_child_sortkey             forums_forums.max_child_sortkey%TYPE;
    v_parent_sortkey                forums_messages.tree_sortkey%TYPE;
begin

    if new.parent_id is null
    then

        select '', max_child_sortkey
        into v_parent_sortkey, v_max_child_sortkey
        from forums_forums
        where forum_id = new.forum_id
        for update;

        v_max_child_sortkey := tree_increment_key(v_max_child_sortkey);

        update forums_forums
        set max_child_sortkey = v_max_child_sortkey
        where forum_id = new.forum_id;

    else

        select coalesce(tree_sortkey, ''), max_child_sortkey
        into v_parent_sortkey, v_max_child_sortkey
        from forums_messages
        where message_id = new.parent_id
        for update;

        v_max_child_sortkey := tree_increment_key(v_max_child_sortkey);

        update forums_messages
        set max_child_sortkey = v_max_child_sortkey
        where message_id = new.parent_id;

    end if;

    new.tree_sortkey := v_parent_sortkey || v_max_child_sortkey;

    return new;
end;$$;


ALTER FUNCTION public.forums_mess_insert_tr() OWNER TO simone;

--
-- Name: forums_message__delete(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_message__delete(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
  p_message_id      alias for $1;    
  v_cur             record;
begin

  -- Maintain the forum thread counts

  select into v_cur *
  from forums_messages
  where message_id = p_message_id;

  if v_cur.parent_id is null then
    if v_cur.state = 'approved' then
      update forums_forums
      set thread_count = thread_count - 1,
        approved_thread_count = approved_thread_count - 1
      where forum_id=v_cur.forum_id;
    else
      update forums_forums
      set thread_count = thread_count - 1
      where forum_id=v_cur.forum_id;
    end if;
  elsif v_cur.state = 'approved' then
    update forums_messages
    set approved_reply_count = approved_reply_count - 1,
      reply_count = reply_count - 1
    where message_id = forums_message__root_message_id(v_cur.message_id);
  else
    update forums_messages
    set reply_count = reply_count - 1
    where message_id = forums_message__root_message_id(v_cur.message_id);
  end if;

  perform acs_object__delete(p_message_id);
  return 0;
end;$_$;


ALTER FUNCTION public.forums_message__delete(integer) OWNER TO simone;

--
-- Name: forums_message__delete_thread(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_message__delete_thread(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    p_message_id                    alias for $1;
    v_forum_id                      forums_messages.forum_id%TYPE;
    v_sortkey                       forums_messages.tree_sortkey%TYPE;
    v_message                       RECORD;
begin
    select forum_id, tree_sortkey
    into v_forum_id, v_sortkey
    from forums_messages
    where message_id = p_message_id;

    -- if it is already deleted
    if v_forum_id is null
    then return 0;
    end if;

    -- delete all children
    -- order by tree_sortkey desc to guarantee
    -- that we never delete a parent before its child
    -- sortkeys are beautiful
    for v_message in select *
                     from forums_messages
                     where forum_id = v_forum_id
                     and tree_sortkey between tree_left(v_sortkey) and tree_right(v_sortkey)
                     order by tree_sortkey desc
    loop
        -- Avoid the count bookkeeping down in forums_message__delete
        perform forums_message__delete(v_message.message_id);
    end loop;

    -- delete the message itself
    perform forums_message__delete(p_message_id);

    return 0;
end;$_$;


ALTER FUNCTION public.forums_message__delete_thread(integer) OWNER TO simone;

--
-- Name: forums_message__move_thread_thread_update_reading_info(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_message__move_thread_thread_update_reading_info(p_source_message_id integer, p_source_forum_id integer, p_target_message_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
		v_target_forum_id 			integer;
		v_users									record;
BEGIN
		select forum_id from forums_messages where message_id = p_target_message_id into v_target_forum_id;
		-- for all users that have read target, but not the source, remove target_info
		for v_users in select user_id from forums_reading_info fri where root_message_id  = p_target_message_id and not exists(select 1 from forums_reading_info where root_message_id = p_source_message_id and user_id = fri.user_id)
    loop
				delete from forums_reading_info where root_message_id = p_target_message_id and user_id = v_users.user_id;
				-- down the number of threads read in target forum
				update  forums_reading_info_user set threads_read = threads_read - 1
					where forum_id = v_target_forum_id and user_id = v_users.user_id;
		end loop;
		-- for all users that have read source, down the nummber of thread in source forum and remove reading info four source message since it no longer is root_message_id
		for v_users in select user_id from forums_reading_info where root_message_id = p_source_message_id
		loop
			delete from forums_reading_info where root_message_id = p_source_message_id and user_id = v_users.user_id;
			update  forums_reading_info_user set threads_read = threads_read - 1
					where forum_id = p_source_forum_id and user_id = v_users.user_id;
		end loop;
    return 1;

END;
$$;


ALTER FUNCTION public.forums_message__move_thread_thread_update_reading_info(p_source_message_id integer, p_source_forum_id integer, p_target_message_id integer) OWNER TO simone;

--
-- Name: forums_message__move_thread_update_reading_info(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_message__move_thread_update_reading_info(p_source_message_id integer, p_source_old_root_message_id integer, p_target_message_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
		v_target_forum_id 			integer;
		v_users									record;
BEGIN
	select forum_id from forums_messages where message_id = p_target_message_id into v_target_forum_id;
	raise notice 'v_target_forum_id %', v_target_forum_id;
	-- for all users that have read target, but not the source, remove target_info
	for v_users in select user_id from forums_reading_info fri where root_message_id  = p_target_message_id and not exists(select 1 from forums_reading_info where root_message_id = p_source_old_root_message_id and user_id = fri.user_id)
    loop
			delete from forums_reading_info where root_message_id = p_target_message_id and user_id = v_users.user_id;
			-- down the number of threads read in target forum
			update  forums_reading_info_user set threads_read = threads_read - 1
				where forum_id = v_target_forum_id and user_id = v_users.user_id;
		end loop;
		return 1;

END;
$$;


ALTER FUNCTION public.forums_message__move_thread_update_reading_info(p_source_message_id integer, p_source_old_root_message_id integer, p_target_message_id integer) OWNER TO simone;

--
-- Name: forums_message__move_update_reading_info(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_message__move_update_reading_info(p_message_id integer, p_old_forum_id integer, p_new_forum_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_message           record;
    v_users             record;
    v_read_p            record;
    v_threads           integer;
BEGIN
		raise notice 'updating for message %', p_message_id;
		for v_users in select user_id from forums_reading_info where root_message_id  = p_message_id
    loop
				raise notice 'updating for user %', v_users.user_id;
				-- down the number of threads read in old forum
			  update forums_reading_info_user set threads_read = threads_read - 1
						where forum_id = p_old_forum_id and user_id = v_users.user_id;
				-- up the number of thread read in new forum
				select count(*) into v_threads from forums_reading_info_user
					where forum_id = p_new_forum_id and user_id = v_users.user_id;
				if v_threads = 0 then
					insert into forums_reading_info_user (forum_id,user_id,threads_read)
						values (p_new_forum_id,v_users.user_id,1);
				else
					update forums_reading_info_user set threads_read = threads_read + 1
						where forum_id = p_new_forum_id and user_id = v_users.user_id;
				end if;
		end loop;

    return 1;

END;
$$;


ALTER FUNCTION public.forums_message__move_update_reading_info(p_message_id integer, p_old_forum_id integer, p_new_forum_id integer) OWNER TO simone;

