--
-- Name: forums_message__root_message_id(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_message__root_message_id(integer) RETURNS integer
    LANGUAGE plpgsql STABLE STRICT
    AS $_$
declare
    p_message_id                    alias for $1;
    v_message_id                    forums_messages.message_id%TYPE;
    v_forum_id                      forums_messages.forum_id%TYPE;
    v_sortkey                       forums_messages.tree_sortkey%TYPE;
begin
    select forum_id, tree_sortkey
    into v_forum_id, v_sortkey
    from forums_messages
    where message_id = p_message_id;

    select message_id
    into v_message_id
    from forums_messages
    where forum_id = v_forum_id
    and tree_sortkey = tree_ancestor_key(v_sortkey, 1);

    return v_message_id;
end;
$_$;


ALTER FUNCTION public.forums_message__root_message_id(integer) OWNER TO simone;

--
-- Name: forums_message__set_state(integer, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_message__set_state(integer, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
  p_message_id      alias for $1;
  p_state           alias for $2;
  v_cur             record;
begin

  select into v_cur *
  from forums_messages
  where message_id = p_message_id;

  if v_cur.parent_id is null then
    if p_state = 'approved' and v_cur.state <> 'approved' then
      update forums_forums
      set approved_thread_count = approved_thread_count + 1
      where forum_id=v_cur.forum_id;
    elsif p_state <> 'approved' and v_cur.state = 'approved' then
      update forums_forums
      set approved_thread_count = approved_thread_count - 1
      where forum_id=v_cur.forum_id;
    end if;
  else
    if p_state = 'approved' and v_cur.state <> 'approved' then
      update forums_messages
      set approved_reply_count = approved_reply_count + 1, 
        last_poster = (case when v_cur.posting_date > last_child_post then v_cur.user_id else last_poster end),
        last_child_post = (case when v_cur.posting_date > last_child_post then v_cur.posting_date else last_child_post end)
      where message_id = forums_message__root_message_id(v_cur.message_id);
    elsif p_state <> 'approved' and v_cur.state = 'approved' then
      update forums_messages
      set approved_reply_count = approved_reply_count - 1
      where message_id = forums_message__root_message_id(v_cur.message_id);
    end if;
  end if;

  update forums_messages
  set state = p_state
  where message_id = p_message_id;

  return 0;

end;$_$;


ALTER FUNCTION public.forums_message__set_state(integer, character varying) OWNER TO simone;

--
-- Name: forums_message__thread_close(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_message__thread_close(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    p_message_id                    alias for $1;
    v_forum_id                      forums_messages.forum_id%TYPE;
    v_sortkey                       forums_messages.tree_sortkey%TYPE;
begin
    select forum_id, tree_sortkey
    into v_forum_id, v_sortkey
    from forums_messages
    where message_id = p_message_id;

    update forums_messages
    set open_p = 'f'
    where tree_sortkey between tree_left(v_sortkey) and tree_right(v_sortkey)
    and forum_id = v_forum_id;

    update forums_messages
    set open_p = 'f'
    where message_id = p_message_id;

    return 0;
end;
$_$;


ALTER FUNCTION public.forums_message__thread_close(integer) OWNER TO simone;

--
-- Name: forums_message__thread_open(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_message__thread_open(integer) RETURNS integer
