--
-- Name: forums_message_search__dtrg(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_message_search__dtrg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
     v_root_message_id          forums_messages.message_id%TYPE;
begin
    -- if the deleted msg has a parent then its an UPDATE to a thread, otherwise a DELETE.

    if old.parent_id is null then
        perform search_observer__enqueue(old.message_id,'DELETE');
    else
        v_root_message_id := forums_message__root_message_id(old.parent_id);
        if not v_root_message_id is null then
            perform search_observer__enqueue(v_root_message_id,'UPDATE');
        end if;
    end if;

    return old;
end;$$;


ALTER FUNCTION public.forums_message_search__dtrg() OWNER TO simone;

--
-- Name: forums_message_search__itrg(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_message_search__itrg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    if new.parent_id is null then
        perform search_observer__enqueue(new.message_id,'INSERT');
    else
        perform search_observer__enqueue(forums_message__root_message_id(new.parent_id),'UPDATE');
    end if;
    return new;
end;$$;


ALTER FUNCTION public.forums_message_search__itrg() OWNER TO simone;

