-- Name: forums_message_search__utrg(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_message_search__utrg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    perform search_observer__enqueue(forums_message__root_message_id (old.message_id),'UPDATE');
    return old;
end;$$;


