--
-- Name: forums_reading_info__remove_msg(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_reading_info__remove_msg(p_message_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
		v_forum_id                      integer;
    v_reading                       RECORD;
BEGIN
    select forum_id from forums_messages where message_id = p_message_id into v_forum_id;
	for v_reading in select user_id
                        from forums_reading_info
                        where root_message_id = p_message_id
		loop
			  delete from forums_reading_info 
        where root_message_id = p_message_id and
              user_id = v_reading.user_id;
	UPDATE forums_reading_info_user SET threads_read=threads_read-1 WHERE forum_id= v_forum_id and user_id = v_reading.user_id;
    end loop;
    
    return 0;
END;

$$;


ALTER FUNCTION public.forums_reading_info__remove_msg(p_message_id integer) OWNER TO simone;

--
-- Name: forums_reading_info__user_add_forum(integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_reading_info__user_add_forum(p_forum_id integer, p_user_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_message                       RECORD;
    v_read_p			    RECORD;
BEGIN
    for v_message in select message_id
                        from forums_messages_approved
                        where forum_id = p_forum_id
                        and parent_id is null 
    loop
	select into v_read_p * from forums_reading_info where user_id = p_user_id and root_message_id  = v_message.message_id;
	if NOT FOUND
	then
            insert into forums_reading_info 
            (root_message_id,user_id) 
            values 
            (v_message.message_id,p_user_id);
	end if;
    end loop;
		delete from forums_reading_info_user where forum_id = p_forum_id and user_id = p_user_id;
		insert into forums_reading_info_user (forum_id,user_id,threads_read) VALUES (p_forum_id,p_user_id,(select approved_thread_count from forums_forums where forum_id = p_forum_id));
    return 0;
END;

$$;


ALTER FUNCTION public.forums_reading_info__user_add_forum(p_forum_id integer, p_user_id integer) OWNER TO simone;

--
-- Name: forums_reading_info__user_add_msg(integer, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.forums_reading_info__user_add_msg(p_root_message_id integer, p_user_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_read_p                        RECORD;
		v_forum_id											integer;
		v_exists												boolean;
BEGIN
		select forum_id from forums_messages where message_id = p_root_message_id into v_forum_id;
		select into v_read_p * from forums_reading_info where user_id = p_user_id and root_message_id  = p_root_message_id;
		if NOT FOUND
				then
        insert into forums_reading_info 
            (root_message_id,user_id) 
            values 
            (p_root_message_id,p_user_id);
				SELECT EXISTS(SELECT 1 FROM forums_reading_info_user WHERE forum_id=v_forum_id AND user_id=p_user_id) INTO v_exists;
				if v_exists = true then
					UPDATE forums_reading_info_user SET threads_read=threads_read+1 WHERE forum_id=v_forum_id AND user_id=p_user_id;
		    else
    	    INSERT INTO forums_reading_info_user(forum_id,user_id,threads_read) VALUES (v_forum_id,p_user_id,1);
    		end if;    
    end if;

    return 0;
END;

$$;


ALTER FUNCTION public.forums_reading_info__user_add_msg(p_root_message_id integer, p_user_id integer) OWNER TO simone;

--
-- Name: fs_package_items_delete_trig(); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.fs_package_items_delete_trig() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare

        v_rec   record;
begin

        for v_rec in
        
                -- We want to delete all cr_items entries, starting from the leaves all
                --  the way up the root folder (old.folder_id).
                select c1.item_id, c1.content_type
                from cr_items c1, cr_items c2
                where c2.item_id = old.folder_id
                  and c1.tree_sortkey between c2.tree_sortkey and tree_right(c2.tree_sortkey)
                  and c1.item_id <> old.folder_id
                order by c1.tree_sortkey desc
        loop

                -- DRB: Why can't we just use object delete here?


                -- We delete the item. On delete cascade should take care
                -- of deletion of revisions.
                if v_rec.content_type = 'file_storage_object'
                then
                    raise notice 'Deleting item_id = %',v_rec.item_id;
                    PERFORM content_item__delete(v_rec.item_id);
                end if;

                -- Instead of doing an if-else, we make sure we are deleting a folder.
                if v_rec.content_type = 'content_folder'
                then
                    raise notice 'Deleting folder_id = %',v_rec.item_id;
                    PERFORM content_folder__delete(v_rec.item_id);
                end if;

                -- Instead of doing an if-else, we make sure we are deleting a folder.
                if v_rec.content_type = 'content_symlink'
                then
                    raise notice 'Deleting symlink_id = %',v_rec.item_id;
                    PERFORM content_symlink__delete(v_rec.item_id);
                end if;

                -- Instead of doing an if-else, we make sure we are deleting a folder.
                if v_rec.content_type = 'content_extlink'
                then
                    raise notice 'Deleting folder_id = %',v_rec.item_id;
                    PERFORM content_extlink__delete(v_rec.item_id);
                end if;

        end loop;

        -- We need to return something for the trigger to be activated
        return old;

end;$$;


ALTER FUNCTION public.fs_package_items_delete_trig() OWNER TO simone;

