--
-- Name: fs_root_foldersi; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.fs_root_foldersi AS
 SELECT acs_objects.object_id,
    acs_objects.object_type,
    acs_objects.title AS object_title,
    acs_objects.package_id AS object_package_id,
    acs_objects.context_id,
    acs_objects.security_inherit_p,
    acs_objects.creation_user,
    acs_objects.creation_date,
    acs_objects.creation_ip,
    acs_objects.last_modified,
    acs_objects.modifying_user,
    acs_objects.modifying_ip,
    acs_objects.tree_sortkey,
    acs_objects.max_child_sortkey,
    cr.revision_id,
    cr.title,
    cr.item_id,
    public.content_revision__get_content(cr.revision_id) AS data,
    cr_text.text_data AS text,
    cr.description,
    cr.publish_date,
    cr.mime_type,
    cr.nls_language,
    fs_root_folders.package_id,
    fs_root_folders.folder_id
   FROM public.acs_objects,
    public.cr_revisions cr,
    public.cr_text,
    public.fs_root_folders
  WHERE ((acs_objects.object_id = cr.revision_id) AND (acs_objects.object_id = fs_root_folders.folder_id));


ALTER TABLE public.fs_root_foldersi OWNER TO simone;

--
-- Name: fs_root_folders_f(public.fs_root_foldersi); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.fs_root_folders_f(p_new public.fs_root_foldersi) RETURNS void
    LANGUAGE plpgsql
    AS $$
             declare
               v_revision_id integer;
             begin

               select content_revision__new(
                                     p_new.title,
                                     p_new.description,
                                     now(),
                                     p_new.mime_type,
                                     p_new.nls_language,
                                     case when p_new.text is null 
                                              then p_new.data 
                                              else p_new.text
                                           end,
                                     content_symlink__resolve(p_new.item_id),
                                     p_new.revision_id,
                                     now(),
                                     p_new.creation_user, 
                                     p_new.creation_ip,
                                     p_new.object_package_id
                ) into v_revision_id;
                 insert into fs_root_folders ( folder_id ) values (v_revision_id);
    
   return;
   end;$$;


