--
-- Name: iter_edit_data(character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.iter_edit_data(character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
declare
   data_in   alias for $1;
   data_ws   date;
   data_form varchar;
   data_test varchar;
   data_out  varchar;
begin
   if length(data_in) = 8
   then
      data_form := 'YYYYMMDD';
   else
      data_form := 'YYYY-MM-DD';
   end if;

   data_ws   := to_date(data_in,data_form);
   data_test := to_char(data_ws,data_form);
   if data_test <> data_in
   then
      return 'Error: date not valid';
   end if;
   data_out  := iter_edit_data(data_ws);
   return data_out;
end;$_$;


ALTER FUNCTION public.iter_edit_data(character varying) OWNER TO simone;

--
-- Name: iter_edit_num(double precision, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.iter_edit_num(double precision, integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
declare
   nume       alias for $1;
   deci       alias for $2;
   ws_max_val float := 999999999999999.9999999999;
   ws_min_val float := -99999999999999.9999999999;
   risultato  varchar;
   edit_deci  varchar;
begin
   if deci > 10
   then
      return 'Error: max 10 decimali';
   end if;

   if nume > ws_max_val
   or nume < ws_min_val
   then
      return 'Error: max 14 cifre intere';
   end if;

   if deci < 1
   or deci is null
   then
      edit_deci := '';
   else
      edit_deci := 'd'||rpad(0,deci,0);
   end if;

   risultato := to_char(nume, '999g999g999g999g990'||edit_deci);
   risultato := translate (risultato,',','!');
   risultato := translate (risultato,'.',',');
   risultato := translate (risultato,'!','.');
   risultato := trim (risultato);

   return risultato;

end;$_$;


ALTER FUNCTION public.iter_edit_num(double precision, integer) OWNER TO simone;

