--
-- Name: iter_edit_time(character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.iter_edit_time(character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
declare
   time_in    alias for $1;
   time_trunc varchar;
   time_ws    timestamp;
   time_test  varchar;
   time_out   varchar;
begin
   time_trunc := substr(time_in,1,5);
   time_ws    := to_timestamp(time_trunc,'hh24:mi');
   time_test  := to_char(time_ws,'hh24:mi');
   if time_test <> time_trunc
   then
      return 'Error: time not valid';
   end if;
   time_out  := iter_edit_time(time_ws);
   return time_out;
end;$_$;


