--
-- Name: iter_get_dt_scad(character varying, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.iter_get_dt_scad(character varying, character varying) RETURNS date
    LANGUAGE plpgsql
    AS $_$
declare
   data_documento   alias for $1;
   cod_impianto     alias for $2;
   data_scadenza    date;
   mesi_validita_g  numeric(08);
   mesi_validita_f  numeric(08);
   potenza          numeric(9,2);
   data_doc         date;
begin
   data_doc        := to_date(data_documento, 'YYYYMMDD');
   mesi_validita_g := valid_mod_h from coimtgen where cod_tgen = 1;
   mesi_validita_f := valid_mod_h_b from coimtgen where cod_tgen =1;
   potenza         := a.potenza from coimaimp a where a.cod_impianto = cod_impianto;
   if potenza >= 35.00
   then
       data_scadenza :=  to_char(add_months(data_doc, + to_number(mesi_validita_f,99999990)), 'YYYYMMDD');
   else
       data_scadenza :=  to_char(add_months(data_doc, + to_number(mesi_validita_g,99999990)), 'YYYYMMDD');
   end if;
   return data_scadenza;
end;$_$;


ALTER FUNCTION public.iter_get_dt_scad(character varying, character varying) OWNER TO simone;

--
-- Name: iter_history_desc_manutentore(text, date); Type: FUNCTION; Schema: public; Owner: riccardo
--

CREATE FUNCTION public.iter_history_desc_manutentore(text, date) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
declare

  p_cod_manutentore               alias for $1;
  p_end_date                      alias for $2;

  v_desc_manutentore               varchar(1000);

begin

      select st.desc into v_desc_manutentore
        from (select (cognome || ' ' || coalesce(nome,'')) as desc
                   , current_date as data_validita
                from coimmanu
               where cod_manutentore = p_cod_manutentore

       union 

      select (cognome || ' ' || coalesce(nome,'')) as desc
                   , st_data_validita as data_validita
                from coimmanu_st
               where cod_manutentore = p_cod_manutentore
              ) as st
  where st.data_validita >= p_end_date 
       order by st.data_validita
   limit 1;

    return v_desc_manutentore;

end;$_$;


ALTER FUNCTION public.iter_history_desc_manutentore(text, date) OWNER TO riccardo;

