--
-- Name: news__revision_new(integer, timestamp with time zone, text, character varying, text, character varying, integer, timestamp with time zone, integer, timestamp with time zone, character varying, timestamp with time zone, character varying, integer, boolean, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.news__revision_new(integer, timestamp with time zone, text, character varying, text, character varying, integer, timestamp with time zone, integer, timestamp with time zone, character varying, timestamp with time zone, character varying, integer, boolean, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    p_item_id                alias for $1;
    --
    p_publish_date           alias for $2;  -- default null
    p_text                   alias for $3;  -- default null
    p_title                  alias for $4;
    --
    -- here goes the revision log
    p_description            alias for $5;
    --
    p_mime_type              alias for $6;  -- default 'text/plain'
    p_package_id             alias for $7;  -- default null
    p_archive_date           alias for $8;  -- default null
    p_approval_user          alias for $9;  -- default null
    p_approval_date          alias for $10; -- default null
    p_approval_ip            alias for $11; -- default null
    --
    p_creation_date          alias for $12; -- default current_timestamp
    p_creation_ip            alias for $13; -- default null
    p_creation_user          alias for $14; -- default null
    --
    p_make_active_revision_p alias for $15; -- default 'f'
    p_lead                   alias for $16;

    v_revision_id    integer;
begin
    -- create revision
    v_revision_id := content_revision__new(
        p_title,         -- title
        p_description,   -- description
        p_publish_date,  -- publish_date
        p_mime_type,     -- mime_type
        null,            -- nls_language
        p_text,          -- text
        p_item_id,       -- item_id
        null,            -- revision_id
        p_creation_date, -- creation_date
        p_creation_user, -- creation_user
        p_creation_ip    -- creation_ip
    );
    -- create new news entry with new revision
    insert into cr_news
        (news_id, 
         lead,
         package_id,
         archive_date, 
         approval_user, 
         approval_date, 
         approval_ip)
    values
        (v_revision_id, 
         p_lead,
         p_package_id,
         p_archive_date, 
         p_approval_user, 
         p_approval_date,
         p_approval_ip);
    -- make active revision if indicated
    if p_make_active_revision_p = 't' then
        PERFORM news__revision_set_active(v_revision_id);
    end if;
    return v_revision_id;
end;
$_$;


ALTER FUNCTION public.news__revision_new(integer, timestamp with time zone, text, character varying, text, character varying, integer, timestamp with time zone, integer, timestamp with time zone, character varying, timestamp with time zone, character varying, integer, boolean, character varying) OWNER TO simone;

--
-- Name: news__revision_set_active(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.news__revision_set_active(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    p_revision_id alias for $1;
    v_news_item_p boolean;
    v_item_id cr_items.item_id%TYPE;
    v_title acs_objects.title%TYPE;
    -- could be used to check if really a 'news' item
begin

    select item_id, title into v_item_id, v_title
    from cr_revisions
    where revision_id = p_revision_id;

    update cr_items
    set live_revision = p_revision_id,
        publish_status = 'ready'
    where item_id = v_item_id;

    -- We update the acs_objects title as well.

    update acs_objects set title = v_title
    where object_id = v_item_id and (title != v_title or title is null);

    return 0;
end;
$_$;


ALTER FUNCTION public.news__revision_set_active(integer) OWNER TO simone;

--
-- Name: news__set_approve(integer, character varying, timestamp with time zone, timestamp with time zone, integer, timestamp with time zone, character varying, boolean); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.news__set_approve(integer, character varying, timestamp with time zone, timestamp with time zone, integer, timestamp with time zone, character varying, boolean) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
    p_revision_id     alias for $1;
    p_approve_p       alias for $2; -- default 't'
    p_publish_date    alias for $3; -- default null
    p_archive_date    alias for $4; -- default null
    p_approval_user   alias for $5; -- default null
    p_approval_date   alias for $6; -- default current_timestamp
    p_approval_ip     alias for $7; -- default null
    p_live_revision_p alias for $8; -- default 't'
    v_item_id         cr_items.item_id%TYPE;
begin
    select item_id into v_item_id
    from   cr_revisions 
    where  revision_id = p_revision_id;
    -- unapprove an revision (does not mean to knock out active revision)
    if p_approve_p = 'f' then
        update  cr_news 
        set     approval_date = null,
                approval_user = null,
                approval_ip   = null,
                archive_date  = null
        where   news_id = p_revision_id;
        --
        update  cr_revisions
        set     publish_date = null
        where   revision_id  = p_revision_id;
    else
    -- approve a revision
        update  cr_revisions
        set     publish_date  = p_publish_date
        where   revision_id   = p_revision_id;
        --  
        update  cr_news 
        set archive_date  = p_archive_date,
            approval_date = p_approval_date,
            approval_user = p_approval_user,
            approval_ip   = p_approval_ip
        where news_id     = p_revision_id;
        -- 
        -- cannot use content_item.set_live_revision because it sets publish_date to sysdate
        if p_live_revision_p = 't' then
            update  cr_items
            set     live_revision = p_revision_id,
                    publish_status = 'ready'
            where   item_id = v_item_id;
        end if;
        --
    end if;

    return 0;
end;
$_$;


ALTER FUNCTION public.news__set_approve(integer, character varying, timestamp with time zone, timestamp with time zone, integer, timestamp with time zone, character varying, boolean) OWNER TO simone;

--
-- Name: news__status(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.news__status(timestamp with time zone, timestamp with time zone) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
declare
    p_publish_date alias for $1;
    p_archive_date alias for $2;
begin
    if p_publish_date is not null then
        if p_publish_date > current_timestamp then
            -- Publishing in the future
            if p_archive_date is null then 
                return 'going_live_no_archive';
            else 
                return 'going_live_with_archive';
            end if;  
        else
            -- Published in the past
            if p_archive_date is null then
                 return 'published_no_archive';
            else
                if p_archive_date > current_timestamp then
                     return 'published_with_archive';
                else 
                    return 'archived';
                end if;
            end if;
        end if;
    else
        -- publish_date null
        return 'unapproved';
    end if;
end;
$_$;


ALTER FUNCTION public.news__status(timestamp with time zone, timestamp with time zone) OWNER TO simone;

--
-- Name: next_day(timestamp with time zone, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.next_day(timestamp with time zone, character varying) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    AS $_$
declare
       next_day__somedate	alias for $1;
       next_day__weekday	alias for $2;
       v_dow			integer;
       v_ref_dow		integer;
       v_add_days		integer;
begin
	-- I cant find a function that converts days of the week to
	-- the corresponding integer value, so I roll my own (above)
	-- We avoid extract(dow from timestamp) because of incompatible output with to_char.
	v_ref_dow := dow_to_int(next_day__weekday);
	v_dow := to_number(to_char(next_day__somedate,'D'),'9');
	
	-- If next_day___weekday is the same day of the week as
	-- next_day__somedate, we add a full week.
	if v_dow < v_ref_dow
	then
	     v_add_days := v_ref_dow - v_dow;
        else
	     v_add_days := v_ref_dow - v_dow + 7;
	end if;

	-- Do date math
	return next_day__somedate + to_interval(v_add_days,'days');

end;$_$;


