--
-- Name: recurrence__new(character varying, integer, character varying, timestamp with time zone, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.recurrence__new(character varying, integer, character varying, timestamp with time zone, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$	-- recurrences.recurrence_id%TYPE
declare
       new__interval_name	  alias for $1; 
       new__every_nth_interval   alias for $2;
       new__days_of_week         alias for $3; -- default null,
       new__recur_until          alias for $4; -- default null,
       new__custom_func          alias for $5; -- default null
       v_recurrence_id		  recurrences.recurrence_id%TYPE;
       v_interval_type_id	  recurrence_interval_types.interval_type%TYPE;
begin

       select nextval('recurrence_sequence') into v_recurrence_id from dual;
        
       select interval_type
       into   v_interval_type_id 
       from   recurrence_interval_types
       where  interval_name = new__interval_name;
        
       insert into recurrences
            (recurrence_id, 
             interval_type, 
             every_nth_interval, 
             days_of_week,
             recur_until, 
             custom_func)
       values
            (v_recurrence_id, 
             v_interval_type_id, 
             new__every_nth_interval, 
             new__days_of_week,
             new__recur_until, 
             new__custom_func);
         
       return v_recurrence_id;

end;$_$;


