--
-- Name: timespan__multi_interval_p(integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.timespan__multi_interval_p(integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
declare
       multi_interval_p__timespan_id   alias for $1;
       v_result                 boolean;
begin
       -- 'f' if 0 or 1 intervals, 't' otherwise
       -- use the simple case syntax
       select (case count(timespan_id) 
                    when 0 then false
                    when 1 then false 
                    else true
               end)
       into v_result
       from timespans
       where timespan_id = multi_interval_p__timespan_id;
        
       return v_result;

end;$_$;


