--
-- Name: timezone__add_rule(character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.timezone__add_rule(character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
declare
  p_tz alias for $1;
  p_abbrev alias for $2;
  p_isdst_p alias for $3;
  p_gmt_offset alias for $4;
  p_utc_start alias for $5;
  p_utc_end alias for $6;
  p_local_start alias for $7;
  p_local_end alias for $8;
begin
  insert into timezone_rules
    (tz_id, abbrev, utc_start, utc_end, local_start, local_end, gmt_offset, isdst_p)
  select timezone__get_id(p_tz), p_abbrev, rdbms_date(p_utc_start),
    rdbms_date(p_utc_end), rdbms_date(p_local_start),
    to_date(p_local_end),
    p_gmt_offset,
    case p_isdst_p when 0 then 'f' else 't'end;
end;$_$;


ALTER FUNCTION public.timezone__add_rule(character varying, character varying, integer, character varying, character varying, character varying, character varying, character varying) OWNER TO simone;

--
-- Name: timezone__convert_to_local(integer, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.timezone__convert_to_local(integer, character varying) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    AS $_$
declare
  p_tz_id alias for $1;
  p_utc_varchar alias for $2;
  v_base_time timestamptz;
begin

  select "timestamptz" (p_utc_varchar || substr(gmt_offset,1,5)) into v_base_time
  from timezones
  where tz_id = p_tz_id;

  if not found then
    return "timestamptz" (p_utc_varchar || '+00');
  end if;

  return "timestamptz" (p_utc_varchar) + "interval" (gmt_offset || 'seconds')
  from   timezone_rules
  where  tz_id = p_tz_id and v_base_time between utc_start and utc_end;

end;$_$;


ALTER FUNCTION public.timezone__convert_to_local(integer, character varying) OWNER TO simone;

--
-- Name: timezone__convert_to_utc(integer, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.timezone__convert_to_utc(integer, character varying) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    AS $_$
declare
  p_tz_id alias for $1;
  p_local_varchar alias for $2;
  v_base_time timestamptz;
begin

  select "timestamptz" (p_local_varchar || substr(gmt_offset,1,5)) into v_base_time
  from timezones
  where tz_id = p_tz_id;

  if not found then
    return "timestamptz" (p_local_varchar || '+00');
  end if;

  return "timestamptz" (p_local_varchar) - "interval" (gmt_offset || 'seconds')
  from   timezone_rules
  where  tz_id = p_tz_id and v_base_time between utc_start and utc_end;

end;$_$;


ALTER FUNCTION public.timezone__convert_to_utc(integer, character varying) OWNER TO simone;

