--
-- Name: timezone__get_rawoffset(integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.timezone__get_rawoffset(integer, timestamp with time zone) RETURNS interval
    LANGUAGE plpgsql STABLE
    AS $_$
declare
  p_tz_id alias for $1;
  p_time alias for $2;
  v_offset varchar;
begin
  v_offset := '0';

  select
    case isdst_p
    when 't' then "interval" (gmt_offset || 'seconds') - '3600 seconds'
    else "interval" (gmt_offset || 'seconds')
    end
  into v_offset
  from   timezone_rules
  where  tz_id  = p_tz_id and p_time between utc_start and utc_end;

  return v_offset;
end;$_$;


