--
-- Name: tree_key_to_int(bit varying, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.tree_key_to_int(bit varying, integer) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$

-- Convert the compressed key for the node at the given level to an 
-- integer.

declare
  p_tree_key      alias for $1;
  p_level         alias for $2;
  v_level         integer default 0;
  v_parent_pos    integer default 1;
  v_pos           integer default 1;
begin

  -- Find the right key first
  while v_pos < length(p_tree_key) and v_level < p_level loop
    v_parent_pos := v_pos;
    v_level := v_level + 1;
    if substring(p_tree_key, v_pos, 1) = '1' then
      v_pos := v_pos + 32;
    else
      v_pos := v_pos + 8;
    end if;
  end loop;

  if v_level < p_level then
    raise exception 'tree_key_to_int: key is at a level less than %', p_level;
  end if;

  if substring(p_tree_key, v_parent_pos, 1) = '1' then
    return bittoint4(substring(p_tree_key, v_parent_pos + 1, 31));
  else
    return bittoint4(substring(p_tree_key, v_parent_pos, 8));
  end if;

end;$_$;


ALTER FUNCTION public.tree_key_to_int(bit varying, integer) OWNER TO simone;

--
-- Name: tree_leaf_key_to_int(bit varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.tree_leaf_key_to_int(bit varying) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$

-- Convert the bitstring for the last, or leaf, node represented by this key
-- to an integer.

declare
  p_tree_key      alias for $1;
  v_leaf_pos      integer default 1;
  v_pos           integer default 1;
begin

  -- Find the leaf key first
  while v_pos < length(p_tree_key) loop
    v_leaf_pos := v_pos;
    if substring(p_tree_key, v_pos, 1) = '1' then
      v_pos := v_pos + 32;
    else
      v_pos := v_pos + 8;
    end if;
  end loop;

  if substring(p_tree_key, v_leaf_pos, 1) = '1' then
    return bittoint4(substring(p_tree_key, v_leaf_pos + 1, 31));
  else
    return bittoint4(substring(p_tree_key, v_leaf_pos, 8));
  end if;

end;$_$;


ALTER FUNCTION public.tree_leaf_key_to_int(bit varying) OWNER TO simone;

--
-- Name: tree_left(bit varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.tree_left(bit varying) RETURNS bit varying
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

-- Create a key less than or equal to that of any child of the
-- current key.

declare
  key      alias for $1;
begin
  if key is null then
    return 'X00'::varbit;
  else
    return key || 'X00'::varbit;
  end if;
end;$_$;


ALTER FUNCTION public.tree_left(bit varying) OWNER TO simone;

--
-- Name: tree_level(bit varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.tree_level(bit varying) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

-- Return the tree level of the given key.  The root level is defined
-- to be at level one.

declare
  p_tree_key           alias for $1;
  v_pos                integer;        
  v_level              integer;
  
begin

  if p_tree_key is null then
    return 0;
  end if;

  v_pos := 1;
  v_level := 0;

  while v_pos <= length(p_tree_key) loop
    v_level := v_level + 1;
    if substring(p_tree_key, v_pos, 1) = '1' then
      v_pos := v_pos + 32;
    else
      v_pos := v_pos + 8;
    end if;
  end loop;

  return v_level;
end;$_$;


ALTER FUNCTION public.tree_level(bit varying) OWNER TO simone;

--
-- Name: tree_next_key(bit varying, integer); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.tree_next_key(bit varying, integer) RETURNS bit varying
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare
  p_parent_key      alias for $1;
  p_child_value     alias for $2;
  v_child_value     integer;
begin
-- Create a new child of the given key with a leaf key number one greater than
-- the child value parameter.  If the child value parameter is null, make the
-- child the first child of the parent.

  if p_child_value is null then
    v_child_value := 0;
  else
    v_child_value := p_child_value + 1;
  end if;

  if p_parent_key is null then
    return int_to_tree_key(v_child_value);
  else
    return p_parent_key || int_to_tree_key(v_child_value);
  end if;

end;$_$;


ALTER FUNCTION public.tree_next_key(bit varying, integer) OWNER TO simone;

--
-- Name: tree_right(bit varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.tree_right(bit varying) RETURNS bit varying
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

-- Create a key greater or equal to that of any child of the current key.
-- Used in BETWEEN expressions to select the subtree rooted at the given
-- key. 

declare
  key      alias for $1;
begin
  if key is null then
    return 'XFFFFFFFF'::varbit;
  else
    return key || 'XFFFFFFFF'::varbit;
  end if;
end;$_$;


ALTER FUNCTION public.tree_right(bit varying) OWNER TO simone;

--
-- Name: tree_root_key(bit varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.tree_root_key(bit varying) RETURNS bit varying
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$

-- Return the tree_sortkey for the root node of the node with the 
-- given tree_sortkey.  

declare
  p_tree_key      alias for $1;
begin

  if substring(p_tree_key, 1, 1) = '1' then
      return substring(p_tree_key, 1, 32);
  else
      return substring(p_tree_key, 1, 8);
  end if;

end;$_$;


