--
-- Name: user_profile_rel__new(integer, character varying, integer, integer, integer, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.user_profile_rel__new(integer, character varying, integer, integer, integer, character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
	p_rel_id		alias for $1;
	p_rel_type		alias for $2;
	p_group_id		alias for $3;
	p_user_id		alias for $4;
	p_creation_user		alias for $5;
	p_creation_ip		alias for $6;
        v_rel_id                membership_rels.rel_id%TYPE;
        v_group_id              groups.group_id%TYPE;
BEGIN
        if p_group_id is null then
            select min(group_id)
            into v_group_id
            from profiled_groups
            where profile_provider = (select min(impl_id)
                                      from acs_sc_impls
                                      where impl_name = 'user_profile_provider');
        else
             v_group_id := p_group_id;
        end if;

        v_rel_id := membership_rel__new(
            p_rel_id,
            p_rel_type,
            v_group_id,
            p_user_id,
	    'approved',
            p_creation_user,
            p_creation_ip
        );

        insert
        into user_profile_rels
        (rel_id)
        values
        (v_rel_id);

        return v_rel_id;
END;
$_$;


