--
-- Name: wal_add_holder_user(numeric, numeric, numeric, numeric, character varying, character varying, character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.wal_add_holder_user(service numeric, sub_service numeric, user_id numeric, source_id numeric, filename character varying, user_name character varying, fiscal_code character varying, iva_code character varying, city character varying, cestec_user_name character varying, iban character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare
  wallet_id character varying(18);
  exist numeric default(0);
begin
  select count(*)
    into exist
    from (select to_number(substring(h.wallet_id from 1 for 3), '999') as w_service,
                 to_number(substring(h.wallet_id from 4 for 1), '9') as w_sub_service,
                 to_number(substring(h.wallet_id from 5 for 6), '999999') as w_user_id
            from wal_holders as h) as u
   where u.w_service = service
     and u.w_sub_service = sub_service
     and u.w_user_id = user_id;
  if (exist>0) then
    raise exception 'User already exist in wal_holders';
  end if;
  wallet_id := wal_create_wallet_id(service, sub_service, user_id);
  insert into wal_holders
    select nextval('wal_holders_cened_seq'),
           wallet_id,
           source_id,
           filename,
           upper(user_name),
           upper(fiscal_code),
           iva_code,
           upper(city),
           cestec_user_name,
           iban;
  --commit;
  return wallet_id;
end;
$$;


ALTER FUNCTION public.wal_add_holder_user(service numeric, sub_service numeric, user_id numeric, source_id numeric, filename character varying, user_name character varying, fiscal_code character varying, iva_code character varying, city character varying, cestec_user_name character varying, iban character varying) OWNER TO simone;

--
-- Name: wal_create_wallet_id(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: simone
--

CREATE FUNCTION public.wal_create_wallet_id(service numeric, sub_service numeric, user_id numeric) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
declare
  wid numeric(18) default 0;
  wallet_id character varying(18);
  rnd numeric;
begin
  if (service>999 or service<0) then 
    raise exception 'Service must be < 1000';
  end if;
  if (sub_service>9 or sub_service<0) then 
    raise exception 'Service must be < 10';
  end if;
  if (user_id>1000000 or user_id<0) then 
    raise exception 'User_id must be < 1000000';
  end if;

  -- setseed(double precision)
  rnd := RANDOM();
  wid = service * 1000000000000000;
  wid := wid + sub_service * 100000000000000;
  wid := wid + user_id * 100000000;
  wid := wid + rnd * 100000000;

  return to_char(wid,'FM099999999999999999');
end;
$$;


ALTER FUNCTION public.wal_create_wallet_id(service numeric, sub_service numeric, user_id numeric) OWNER TO simone;

