    dependency_type character varying(20) NOT NULL,
    service_uri character varying(1500) NOT NULL,
    service_version character varying(100) NOT NULL,
    CONSTRAINT apm_package_deps_type_ck CHECK (((dependency_type)::text = ANY (ARRAY[('provides'::character varying)::text, ('requires'::character varying)::text, ('extends'::character varying)::text, ('embeds'::character varying)::text])))
);


ALTER TABLE public.apm_package_dependencies OWNER TO simone;

--
-- Name: TABLE apm_package_dependencies; Type: COMMENT; Schema: public; Owner: simone
--

COMMENT ON TABLE public.apm_package_dependencies IS '
 This table indicates what services are provided or required by a particular version.
';


--
-- Name: COLUMN apm_package_dependencies.service_version; Type: COMMENT; Schema: public; Owner: simone
--

COMMENT ON COLUMN public.apm_package_dependencies.service_version IS '
 The restrictions on service version should match those on apm_package_versions.version_name.
';


--
-- Name: apm_package_owners; Type: TABLE; Schema: public; Owner: simone
