';


--
-- Name: application_group_segments; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.application_group_segments AS
 SELECT g.package_id,
    s.segment_id,
    s.group_id,
    s.rel_type,
    s.segment_name
   FROM public.application_groups g,
    public.group_element_map m,
    public.rel_segments s
  WHERE ((g.group_id = m.group_id) AND (m.element_id = s.group_id))
UNION ALL
 SELECT g.package_id,
    s.segment_id,
    s.group_id,
    s.rel_type,
    s.segment_name
   FROM public.application_groups g,
    public.rel_segments s
  WHERE (g.group_id = s.group_id);


ALTER TABLE public.application_group_segments OWNER TO simone;

