--
-- Name: coimuten_view_new_autorizz_2014_05_20; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.coimuten_view_new_autorizz_2014_05_20 AS
 SELECT result_table1.id_utente,
    result_table1.cognome,
    result_table1.nome,
    result_table1.password,
    (rtrim(substr(result_table1.group_name, 1, result_table1.pos_primo_spazio)))::character varying(20) AS id_settore,
    (rtrim(substr(result_table1.group_name, (result_table1.pos_primo_spazio + 1), result_table1.lun_seconda_stringa)))::character varying(20) AS id_ruolo,
    result_table1.lingua,
    result_table1.e_mail,
    result_table1.rows_per_page,
    result_table1.data,
    (substr(result_table1.group_name, ((result_table1.pos_primo_spazio + result_table1.lun_seconda_stringa) + 1)))::numeric(1,0) AS livello
   FROM ( SELECT a.username AS id_utente,
            c.last_name AS cognome,
            c.first_names AS nome,
            a.password,
            lower((e.group_name)::text) AS group_name,
            public.instr(e.group_name, ' '::bpchar) AS pos_primo_spazio,
            public.instr((substr((e.group_name)::text, (public.instr(e.group_name, ' '::bpchar) + 1)))::character varying, ' '::bpchar) AS lun_seconda_stringa,
            'it'::character varying(2) AS lingua,
            b.email AS e_mail,
            (30)::numeric(8,0) AS rows_per_page,
            (date(a.password_changed_date) + 91) AS data
           FROM public.users a,
            public.parties b,
            public.persons c,
            public.acs_rels d,
            public.groups e
          WHERE ((b.party_id = a.user_id) AND (c.person_id = b.party_id) AND ((d.rel_type)::text = 'membership_rel'::text) AND (d.object_id_two = a.user_id) AND (d.object_id_one > 0) AND (e.group_id = d.object_id_one))) result_table1;


ALTER TABLE public.coimuten_view_new_autorizz_2014_05_20 OWNER TO simone;

