-- Name: TABLE rel_constraints; Type: COMMENT; Schema: public; Owner: simone
--

COMMENT ON TABLE public.rel_constraints IS '
  Defines relational constraints. The relational constraints system is
  intended to support applications in modelling and applying
  constraint rules on inter-party relatinships based on relational
  party segmentation.
';


--
-- Name: COLUMN rel_constraints.constraint_name; Type: COMMENT; Schema: public; Owner: simone
--

COMMENT ON COLUMN public.rel_constraints.constraint_name IS '
  The user-defined name of this constraint.
';


--
-- Name: COLUMN rel_constraints.rel_segment; Type: COMMENT; Schema: public; Owner: simone
--

COMMENT ON COLUMN public.rel_constraints.rel_segment IS '
  The segment for which the constraint is defined.
';


--
-- Name: COLUMN rel_constraints.rel_side; Type: COMMENT; Schema: public; Owner: simone
--

COMMENT ON COLUMN public.rel_constraints.rel_side IS '
  The side of the relation the constraint applies to.
';


--
-- Name: COLUMN rel_constraints.required_rel_segment; Type: COMMENT; Schema: public; Owner: simone
--

COMMENT ON COLUMN public.rel_constraints.required_rel_segment IS '
  The segment in which elements must be in to satisfy the constraint.
';


--
-- Name: rel_segment_party_map; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.rel_segment_party_map AS
 SELECT rs.segment_id,
    gem.element_id AS party_id,
    gem.rel_id,
    gem.rel_type,
    gem.group_id,
    gem.container_id,
    gem.ancestor_rel_type
   FROM public.rel_segments rs,
    public.group_element_map gem,
    public.acs_object_types o1,
    public.acs_object_types o2
  WHERE ((gem.group_id = rs.group_id) AND ((o1.object_type)::text = (gem.rel_type)::text) AND ((o2.object_type)::text = (rs.rel_type)::text) AND ((o1.tree_sortkey >= o2.tree_sortkey) AND (o1.tree_sortkey <= public.tree_right(o2.tree_sortkey))));


ALTER TABLE public.rel_segment_party_map OWNER TO simone;

--
-- Name: constrained_rels1; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.constrained_rels1 AS
 SELECT rel.constraint_id,
    rel.constraint_name,
    r.rel_id,
    r.container_id,
    r.party_id,
    r.rel_type,
    rel.rel_segment,
    rel.rel_side,
    rel.required_rel_segment
   FROM public.rel_constraints rel,
    public.rel_segment_party_map r
  WHERE ((rel.rel_side = 'one'::bpchar) AND (rel.rel_segment = r.segment_id));


ALTER TABLE public.constrained_rels1 OWNER TO simone;

--
-- Name: constrained_rels2; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.constrained_rels2 AS
 SELECT rel.constraint_id,
    rel.constraint_name,
    r.rel_id,
    r.container_id,
    r.party_id,
    r.rel_type,
    rel.rel_segment,
    rel.rel_side,
    rel.required_rel_segment
   FROM public.rel_constraints rel,
    public.rel_segment_party_map r
  WHERE ((rel.rel_side = 'two'::bpchar) AND (rel.rel_segment = r.segment_id));


ALTER TABLE public.constrained_rels2 OWNER TO simone;

