-- Name: cr_newsx; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.cr_newsx AS
 SELECT acs_objects.object_id,
    acs_objects.object_type,
    acs_objects.title AS object_title,
    acs_objects.package_id AS object_package_id,
    acs_objects.context_id,
    acs_objects.security_inherit_p,
    acs_objects.creation_user,
    acs_objects.creation_date,
    acs_objects.creation_ip,
    acs_objects.last_modified,
    acs_objects.modifying_user,
    acs_objects.modifying_ip,
    acs_objects.tree_sortkey,
    acs_objects.max_child_sortkey,
    cr.revision_id,
    cr.title,
    cr.item_id,
    cr.description,
    cr.publish_date,
    cr.mime_type,
    cr.nls_language,
    i.name,
    i.parent_id,
    cr_news.news_id,
    cr_news.lead,
    cr_news.package_id,
    cr_news.archive_date,
    cr_news.approval_user,
    cr_news.approval_date,
    cr_news.approval_ip
   FROM public.acs_objects,
    public.cr_revisions cr,
    public.cr_items i,
    public.cr_text,
    public.cr_news
  WHERE ((acs_objects.object_id = cr.revision_id) AND (cr.item_id = i.item_id) AND (acs_objects.object_id = cr_news.news_id));


