--
-- Name: curit_crm_contacts; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.curit_crm_contacts AS
 SELECT t.id_utente,
    t.email,
    t.first_names AS nome,
    t.last_name AS cognome,
    t.rag_sociale,
    t.fiscal_code AS cod_fiscale,
    t.iva_code AS p_iva,
    t.address1 AS indirizzo,
    t.city AS comune,
    t.province AS prov,
    t.zipcode AS cap,
    t.phone AS tel,
    t.fax,
    t.mobile AS cell,
    t.notes AS note,
    t.titolo,
    t.editing_date AS last_update,
    t.iter_code,
    t.status,
    t.community
   FROM ( SELECT p.first_names,
            p.last_name,
            ('CAIT_'::text || (c.cait_id)::text) AS id_utente,
            c.name AS rag_sociale,
            c.address1,
            c.city,
            c.province,
            c.zipcode,
            c.fiscal_code,
            c.iva_code,
            c.phone,
            c.mobile,
            c.email,
            c.fax,
            'CAIT'::text AS titolo,
            c.notes,
            c.editing_date,
            'ND'::text AS iter_code,
            2 AS status,
            'CURIT'::text AS community
           FROM (public.iter_cait c
             LEFT JOIN public.persons p ON ((c.cait_id = p.person_id)))
        UNION ALL
         SELECT p.first_names,
            p.last_name,
            ('DIST_'::text || (d.distributor_id)::text),
            d.name,
            d.address1,
            d.city,
            d.province,
            d.zipcode,
            d.fiscal_code,
            d.iva_code,
            d.phone,
            d.mobile,
            d.email,
            d.fax,
            'DISTRIBUTORE'::text AS text,
            d.notes,
            d.editing_date,
            'ND'::text AS iter_code,
            2 AS status,
            'CURIT'::text AS community
           FROM (public.iter_distributors d
             LEFT JOIN public.persons p ON ((d.distributor_id = p.person_id)))
        UNION ALL
         SELECT p.first_names,
            p.last_name,
            ('MAN_'::text || (m.maintainer_id)::text),
            m.name,
            m.address1,
            m.city,
            m.province,
            m.zipcode,
            m.fiscal_code,
            m.iva_code,
            m.phone,
            m.mobile,
            m.email,
            m.fax,
            'MANUTENTORE'::text AS text,
            m.notes,
            m.editing_date,
            m.iter_code,
            2 AS status,
            'CURIT'::text AS community
           FROM (public.iter_maintainers m
             LEFT JOIN public.persons p ON ((m.maintainer_id = p.person_id)))
        UNION ALL
         SELECT p.first_names,
            p.last_name,
            ('AMM_'::text || (t_1.trustee_id)::text),
            t_1.name,
            t_1.address1,
            t_1.city,
            t_1.province,
            t_1.zipcode,
            t_1.fiscal_code,
            t_1.iva_code,
            t_1.phone,
            t_1.mobile,
            t_1.email,
            t_1.fax,
            'AMMINISTRATORE'::text AS text,
            t_1.notes,
            t_1.editing_date,
            t_1.iter_code,
            2 AS status,
            'CURIT'::text AS community
           FROM (public.iter_trustees t_1
             LEFT JOIN public.persons p ON ((t_1.trustee_id = p.person_id)))
        UNION ALL
         SELECT p.first_names,
            p.last_name,
            ('ISP_'::text || (i.inspector_id)::text),
            i.name,
            i.address1,
            i.city,
            i.province,
            i.zipcode,
            i.fiscal_code,
            i.iva_code,
            i.phone,
            i.mobile,
            i.email,
            i.fax,
            'ISPETTORE'::text AS text,
            i.notes,
            i.editing_date,
            i.iter_code,
            2 AS status,
            'CURIT'::text AS community
           FROM (public.iter_inspectors i
             LEFT JOIN public.persons p ON ((i.inspector_id = p.person_id)))) t;


ALTER TABLE public.curit_crm_contacts OWNER TO simone;

