--
-- Name: dotlrn_guest_status; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.dotlrn_guest_status AS
 SELECT r.object_id_two AS user_id,
        CASE
            WHEN ((r.rel_type)::text = 'dotlrn_guest_rel'::text) THEN 't'::text
            ELSE 'f'::text
        END AS guest_p
   FROM public.acs_rels r,
    public.membership_rels m
  WHERE ((m.rel_id = r.rel_id) AND (((r.rel_type)::text = 'dotlrn_guest_rel'::text) OR ((r.rel_type)::text = 'dotlrn_non_guest_rel'::text)) AND (r.object_id_one = public.acs__magic_object_id('registered_users'::character varying)));


