    acs_objects.last_modified,
    acs_objects.modifying_user,
    acs_objects.modifying_ip,
    acs_objects.tree_sortkey,
    acs_objects.max_child_sortkey,
    cr.revision_id,
    cr.title,
    cr.item_id,
    cr.description,
    cr.publish_date,
    cr.mime_type,
    cr.nls_language,
    i.name,
