--
-- Name: iter_maintainers_view; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.iter_maintainers_view AS
 SELECT m.maintainer_id,
    m.name,
    m.address1,
    m.address2,
    m.city,
    m.province,
    m.zipcode,
    m.fiscal_code,
    m.iva_code,
    m.phone,
    m.mobile,
    m.email,
    m.fax,
    m.associated_to,
    m.where_registered,
    m.registration_no,
    m.where_rea,
    m.rea_no,
    m.capital,
    m.role,
    m.representative_id,
    m.notes,
    m.lotto_no,
    m.validated_p,
    m.validating_user,
    m.validating_date,
    m.iter_code,
    m.company_type,
    m.is_active_p,
    m.creation_user,
    m.creation_date,
    m.editing_user,
    m.editing_date,
    m.op_number,
    m.an_number,
    m.de_number,
    m.approved_p,
    m.cait_id,
    m.wallet_id,
    m.iban_code,
    public.ah_edit_num((m.op_number)::double precision, 0) AS op_number_pretty,
    public.ah_edit_num((m.an_number)::double precision, 0) AS an_number_pretty,
    public.ah_edit_num((m.de_number)::double precision, 0) AS de_number_pretty,
    public.ah_edit_num(m.capital, 2) AS capital_pretty,
        CASE
            WHEN (m.role = '0'::bpchar) THEN 'Installatore'::text
            WHEN (m.role = '0'::bpchar) THEN 'Manutentore'::text
            ELSE 'Installatore/Manutentore'::text
        END AS role_pretty,
    p.name AS rep_name,
    p.first_name AS rep_first_name,
    p.address1 AS rep_address1,
    p.city AS rep_city,
    p.address2 AS rep_address2,
    p.province AS rep_province,
    p.zipcode AS rep_zipcode,
    p.fiscal_code AS rep_fiscal_code
   FROM public.iter_maintainers m,
    public.iter_parties p
  WHERE (m.representative_id = p.party_id);


ALTER TABLE public.iter_maintainers_view OWNER TO simone;

