--
-- Name: mis_fast_scripts; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.mis_fast_scripts AS
 SELECT s.script_id,
    s.description,
    s.original_author,
    s.maintainer,
    s.is_active_p,
    s.is_executable_p,
    o.object_id,
    o.object_type,
    o.title,
    o.package_id,
    o.context_id,
    o.security_inherit_p,
    o.creation_user,
    o.creation_date,
    o.creation_ip,
    o.last_modified,
    o.modifying_user,
    o.modifying_ip,
    o.tree_sortkey,
    o.max_child_sortkey,
    (public.tree_level(o.tree_sortkey) - 2) AS level
   FROM public.mis_scripts s,
    public.acs_objects o
  WHERE (s.script_id = o.object_id);


