--
-- Name: news_item_full_active; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.news_item_full_active AS
 SELECT ci.item_id,
    cn.package_id,
    cr.revision_id,
    cr.title AS publish_title,
    cn.lead AS publish_lead,
    cr.content AS publish_body,
    cr.mime_type AS publish_format,
    cr.publish_date,
    cn.archive_date,
    public.news__status(cr.publish_date, cn.archive_date) AS status,
    ci.name AS item_name,
    ps.person_id AS creator_id,
    (((ps.first_names)::text || ' '::text) || (ps.last_name)::text) AS item_creator
   FROM public.cr_items ci,
    public.cr_revisions cr,
    public.cr_news cn,
    public.acs_objects ao,
    public.persons ps
  WHERE ((cr.item_id = ci.item_id) AND ((cr.revision_id = ci.live_revision) OR ((ci.live_revision IS NULL) AND (cr.revision_id = public.content_item__get_latest_revision(ci.item_id)))) AND (cr.revision_id = cn.news_id) AND (ci.item_id = ao.object_id) AND (ao.creation_user = ps.person_id));


ALTER TABLE public.news_item_full_active OWNER TO simone;

--
-- Name: news_item_revisions; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.news_item_revisions AS
 SELECT cr.item_id,
    cr.revision_id,
    ci.live_revision,
    cr.title AS publish_title,
    cn.lead AS publish_lead,
    cr.content AS publish_body,
    cr.publish_date,
    cn.archive_date,
    cr.description AS log_entry,
    cr.mime_type AS publish_format,
    cr.mime_type,
    cn.package_id,
    (ao.creation_date)::date AS creation_date,
    public.news__status(cr.publish_date, cn.archive_date) AS status,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM public.cr_revisions cr2
              WHERE ((cr2.revision_id = cn.news_id) AND (cr2.publish_date IS NULL)))) THEN 1
            ELSE 0
        END AS approval_needed_p,
    (((ps.first_names)::text || ' '::text) || (ps.last_name)::text) AS item_creator,
    ao.creation_user,
    ao.creation_ip,
    ci.name AS item_name
   FROM public.cr_revisions cr,
    public.cr_news cn,
    public.cr_items ci,
    public.acs_objects ao,
    public.persons ps
  WHERE ((cr.revision_id = ao.object_id) AND (cr.revision_id = cn.news_id) AND (ci.item_id = cr.item_id) AND (ao.creation_user = ps.person_id));


ALTER TABLE public.news_item_revisions OWNER TO simone;

--
-- Name: news_item_unapproved; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.news_item_unapproved AS
 SELECT cr.revision_id,
    ci.name AS item_name,
    (((ps.first_names)::text || ' '::text) || (ps.last_name)::text) AS item_creator,
    ao.creation_ip AS item_creation_ip,
    (ao.creation_date)::date AS creation_date
   FROM public.cr_revisions cr,
    public.cr_items ci,
    public.acs_objects ao,
    public.persons ps
  WHERE ((ci.item_id = cr.item_id) AND (cr.revision_id = ao.object_id) AND (ao.creation_user = ps.person_id));


ALTER TABLE public.news_item_unapproved OWNER TO simone;

--
-- Name: news_items_approved; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.news_items_approved AS
 SELECT ci.item_id,
    cn.package_id,
    cr.title AS publish_title,
    cn.lead AS publish_lead,
    cr.content AS publish_body,
    cr.mime_type AS publish_format,
    to_char(cr.publish_date, 'Mon dd, yyyy'::text) AS pretty_publish_date,
    cr.publish_date,
    ao.creation_user,
    (((ps.first_names)::text || ' '::text) || (ps.last_name)::text) AS item_creator,
    (cn.archive_date)::date AS archive_date
   FROM public.cr_items ci,
    public.cr_revisions cr,
    public.cr_news cn,
    public.acs_objects ao,
    public.persons ps
  WHERE ((ci.item_id = cr.item_id) AND (ci.live_revision = cr.revision_id) AND (cr.revision_id = cn.news_id) AND (cr.revision_id = ao.object_id) AND (ao.creation_user = ps.person_id));


ALTER TABLE public.news_items_approved OWNER TO simone;

--
-- Name: news_items_live_or_submitted; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.news_items_live_or_submitted AS
 SELECT ci.item_id,
    cn.news_id,
    cn.package_id,
    cr.publish_date,
    cn.archive_date,
    cr.title AS publish_title,
    cn.lead AS publish_lead,
    cr.content AS publish_body,
    cr.mime_type AS publish_format,
    ao.creation_user,
    (((ps.first_names)::text || ' '::text) || (ps.last_name)::text) AS item_creator,
    (ao.creation_date)::date AS creation_date,
    ci.live_revision,
    public.news__status(cr.publish_date, cn.archive_date) AS status
   FROM public.cr_items ci,
    public.cr_revisions cr,
    public.cr_news cn,
    public.acs_objects ao,
    public.persons ps
  WHERE (((ci.item_id = cr.item_id) AND (ci.live_revision = cr.revision_id) AND (cr.revision_id = cn.news_id) AND (cr.revision_id = ao.object_id) AND (ao.creation_user = ps.person_id)) OR ((ci.live_revision IS NULL) AND (ci.item_id = cr.item_id) AND (cr.revision_id = public.content_item__get_latest_revision(ci.item_id)) AND (cr.revision_id = cn.news_id) AND (cr.revision_id = ao.object_id) AND (ao.creation_user = ps.person_id)));


ALTER TABLE public.news_items_live_or_submitted OWNER TO simone;

--
-- Name: news_items_unapproved; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.news_items_unapproved AS
 SELECT ci.item_id,
    cr.title AS publish_title,
    cn.lead AS publish_lead,
    cn.package_id,
    (ao.creation_date)::date AS creation_date,
    (((ps.first_names)::text || ' '::text) || (ps.last_name)::text) AS item_creator
   FROM public.cr_items ci,
    public.cr_revisions cr,
    public.cr_news cn,
    public.acs_objects ao,
    public.persons ps
  WHERE ((cr.revision_id = ao.object_id) AND (ao.creation_user = ps.person_id) AND (cr.revision_id = public.content_item__get_live_revision(ci.item_id)) AND (cr.revision_id = cn.news_id) AND (cr.item_id = ci.item_id) AND (cr.publish_date IS NULL));


ALTER TABLE public.news_items_unapproved OWNER TO simone;

