--
-- Name: wal_dbl_trans; Type: VIEW; Schema: public; Owner: simone
--

CREATE VIEW public.wal_dbl_trans AS
 SELECT tmp.filename,
    tmp.reference,
    tmp.holder_id,
    tmp.payment_date,
    tmp.n
   FROM ( SELECT wal_transactions.filename,
            wal_transactions.reference,
            wal_transactions.holder_id,
            wal_transactions.payment_date,
            count(*) AS n
           FROM public.wal_transactions
          WHERE (wal_transactions.pay_type_id = 2)
          GROUP BY wal_transactions.filename, wal_transactions.reference, wal_transactions.holder_id, wal_transactions.payment_date) tmp
  WHERE (tmp.n > 1);


