    cr.revision_id,
    cr.item_id,
    cr.title,
    cr.description,
    cr.publish_date,
    cr.mime_type,
    cr.nls_language,
    cr.lob,
    cr.content,
    cr.content_length,
    ci.parent_id,
    ci.name,
    ci.locale,
